--  Lithium's crystal logo (256x256 PNG, base64), used as the menu logo.
local LITHIUM_LOGO_B64 = ""

--==========================================================================
--  Kyvweer's bootstrap (b8) and main (j1), as in the dump. Left out of b8:
--  the analytics client (kyvweer.cc), the Luarmor auto-execute writer and the
--  anti-cheat bypass (b7). Kyvweer's online user service (eZ) is offline.
--==========================================================================
local GlobalTrove = tbl17.n()
tbl17.w().ensureStorageDirectories("kyvweerrebuild/rivals")
tbl17.w().ensureStorageDirectories("kyvweerrebuild/fonts")
tbl17.w().ensureStorageDirectories("kyvweerrebuild/cache")
for _, sub in ipairs({ "cosmetics/states", "crosshair_textures", "esp_images", "movement_recorder" }) do
    tbl17.w().ensureStorageDirectories("kyvweerrebuild/rivals/" .. sub)
end

--  KWH logo: written to disk once per load and turned into an asset id
--  for the menu rail and the watermark.
do
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for i = 1, 64 do map[alphabet:byte(i)] = i - 1 end
    local function decode(s)
        local out = buffer.create(#s * 3 // 4 + 3)
        local n = 0
        for i = 1, #s, 4 do
            local a, b, c, d = s:byte(i, i + 3)
            local vc, vd = map[c], map[d]
            local v = map[a] * 262144 + map[b] * 4096 + (vc or 0) * 64 + (vd or 0)
            buffer.writeu8(out, n, bit32.rshift(v, 16))
            n += 1
            if vc then buffer.writeu8(out, n, bit32.band(bit32.rshift(v, 8), 255)) n += 1 end
            if vd then buffer.writeu8(out, n, bit32.band(v, 255)) n += 1 end
        end
        return buffer.readstring(out, 0, n)
    end
    local wrf, gca = K.fn("writefile"), K.fn("getcustomasset") or K.fn("getsynasset")
    if wrf and gca then
        local path = "kyvweerrebuild/kwh_logo.png"
        local ok = pcall(wrf, path, decode(LITHIUM_LOGO_B64))
        local ok2, id = pcall(gca, path)
        if ok2 and id then
            K.LithiumLogo = id
        end
    end
end


--  Kyvweer's error reporter needs a sink; ours prints to the F9 console.
tbl17.b().use({ Report = function(_, e)
    local detail = type(e) == "table" and (e.Detail or e.Operation) or e
    warn("[Kyvweer Rebuild] " .. tostring(detail))
end })

local boot = (function()
    local store = tbl17.bG()
    local profiles = GlobalTrove:Add(tbl17.bN().new(store))
    store:UseMiddleware(profiles)
    local fonts = tbl17.az()
    GlobalTrove:Add(tbl17.aB().use(store, { "Notifications" }, { "Theme" }, function(f) return fonts:Get(f) end,
        tbl17.bI().Notifications))

    local reporter = GlobalTrove:Add(tbl17.ad().new())
    local state = GlobalTrove:Add(tbl17.ae().new("kyvweerrebuild/rivals"))
    local stateData = state:Load()
    if stateData.AutoLoad and stateData.AutoLoadConfigName ~= nil then
        local r = reporter:ReportResult(store:LoadFromFile(stateData.AutoLoadConfigName))
        if not r.Ok then
            local text = "Failed to auto-load the selected config"
            if string.find(r.Error.Detail, "newer than current version", 1, true) ~= nil then
                text = "Your selected config was saved by a newer version - update or pick another config"
            end
            tbl17.aB().get():Notify(text)
        elseif #tbl17.bc().takeDroppedPaths() > 0 then
            tbl17.aB().get():Notify("Some saved settings could not be restored and were reset to defaults")
        end
    end

    local Theme = tbl17.A()
    local theme = store.Data.Theme
    if theme ~= nil then
        for k, v in next, theme do
            if Theme.Tokens[k] ~= nil and typeof(v) == "Color3" then Theme.refresh(k, v) end
        end
    end

    local registry = GlobalTrove:Add(tbl17.bK().new())
    local identities = GlobalTrove:Add(tbl17.bL().new(registry))
    local tags = GlobalTrove:Add(tbl17.bM().new(registry))
    GlobalTrove:Add(tbl17.bR().new(tags, registry))
    GlobalTrove:Add(tbl17.bZ().new(identities))
    local avatar = GlobalTrove:Add(tbl17.b6().new(registry))

    return {
        StoreProfiles = profiles,
        PlayerRegistry = registry,
        PlayerIdentities = identities,
        PlayerTags = tags,
        DecoratorFactory = avatar ~= nil and avatar:GetDecoratorFactory() or nil,
        ArmAvatarSpoofer = function() avatar:Arm() end,
        GeneralState = state,
        GeneralStateData = stateData,
    }
end)()

function K.Unload()
    if K.destroyed then return end
    K.destroyed = true
    for _, f in ipairs(K.cleanups) do pcall(f) end
    pcall(function() GlobalTrove:Destroy() end)
    if getgenv().KyvweerRebuild == K then getgenv().KyvweerRebuild = nil end
end



--==========================================================================
--  Ragebot extras (Lua X port): Sling Bypass, Dagger Bypass,
--  Expand Hitbox, Anti Aim, Translocation
--==========================================================================
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UserInputService = game:GetService("UserInputService")
    local LocalPlayer = Players.LocalPlayer
    local Camera = workspace.CurrentCamera
    local store = tbl17.bG()

    local function cfg(path, default)
        local ok, v = pcall(function() return store:Get(path, true) end)
        if ok and v ~= nil then return v end
        return default
    end

    local function featureOn(section)
        local rb = store.Data and store.Data.Ragebot
        if type(rb) ~= "table" then return false end
        local d = (section == "Ragebot") and rb or rb[section]
        if type(d) ~= "table" then return false end
        local kb = d.Keybind
        if type(kb) == "table" then
            local kind = kb.Kind or "Always"
            if kind == "Hold" then
                return kb.State == true
            end
            if kind == "Toggle" then
                return kb.State == true
            end
            -- Always: ONLY the Enable switch (off = fully off)
            return d.Enabled == true
        end
        return d.Enabled == true
    end

    
    -- Force combat extras OFF at load (never auto-enable)
    pcall(function()
        local rb = store and store.Data and store.Data.Ragebot
        if type(rb) ~= "table" then return end
        for _, key in ipairs({"Ragebot","FakePosition","VoidSpam","SlingBypass","DaggerBypass","ExpandHitbox","AntiAim","CounterUE","CounterSleepy","RapidFire","Arcade"}) do
            local sec = (key == "Ragebot") and rb or rb[key]
            if type(sec) == "table" then
                sec.Enabled = false
                if type(sec.Keybind) == "table" then sec.Keybind.State = false end
            end
        end
        -- main rage enable
        rb.Enabled = false
        if type(rb.Keybind) == "table" then rb.Keybind.State = false end
    end)

    local function getRoot()
        local c = LocalPlayer.Character
        return c and c:FindFirstChild("HumanoidRootPart")
    end

    local function getTarget(mode)
        local root = getRoot()
        if not root then return nil end
        local list = {}
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character then
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    table.insert(list, p)
                end
            end
        end
        if #list == 0 then return nil end
        mode = mode or "Closest"
        if mode == "Random" then return list[math.random(1, #list)] end
        if mode == "Weakest" then
            table.sort(list, function(a, b)
                local ha = a.Character:FindFirstChildOfClass("Humanoid")
                local hb = b.Character:FindFirstChildOfClass("Humanoid")
                return (ha and ha.Health or 0) < (hb and hb.Health or 0)
            end)
            return list[1]
        end
        if mode == "Strongest" then
            table.sort(list, function(a, b)
                local ha = a.Character:FindFirstChildOfClass("Humanoid")
                local hb = b.Character:FindFirstChildOfClass("Humanoid")
                return (ha and ha.Health or 0) > (hb and hb.Health or 0)
            end)
            return list[1]
        end
        local best, bestD = nil, math.huge
        for _, p in ipairs(list) do
            local hrp = p.Character.HumanoidRootPart
            local d = (root.Position - hrp.Position).Magnitude
            if d < bestD then bestD, best = d, p end
        end
        return best
    end

    local function predictPos(hrp, lead)
        lead = lead or 0.15
        local vel = hrp.AssemblyLinearVelocity or Vector3.zero
        return hrp.Position + vel * lead
    end

    local function tpTo(pos, vel)
        local root = getRoot()
        if not root then return end
        pcall(function()
            root.CFrame = CFrame.new(pos)
            root.AssemblyLinearVelocity = vel or Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    end

    ----------------------------------------------------------------
    -- Sling Bypass (full Lua X modes)
    ----------------------------------------------------------------
    local slingConn, slingRenderConn, slingOrbAng, slingHoverT, slingLastShot, slingLastRush
    local slingFollowPos, slingRealCF
    local avatarHidden = false

    local function hideAvatar()
        local ch = LocalPlayer.Character
        if not ch then return end
        for _, part in ipairs(ch:GetDescendants()) do
            if part:IsA("BasePart") then
                pcall(function() part.LocalTransparencyModifier = 1 end)
            elseif part:IsA("Accessory") or part:IsA("Decal") or part:IsA("Texture") then
                pcall(function()
                    if part:IsA("Accessory") then
                        for _, d in ipairs(part:GetDescendants()) do
                            if d:IsA("BasePart") then d.LocalTransparencyModifier = 1 end
                        end
                    end
                end)
            end
        end
        avatarHidden = true
    end

    local function restoreAvatar()
        local ch = LocalPlayer.Character
        if not ch then return end
        for _, part in ipairs(ch:GetDescendants()) do
            if part:IsA("BasePart") then
                pcall(function() part.LocalTransparencyModifier = 0 end)
            end
        end
        avatarHidden = false
    end

    local function doAutoShoot(target)
        if not target or not target.Character then return end
        local tool = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Tool")
        if not tool then return end
        local root = getRoot()
        local hrp = target.Character:FindFirstChild("HumanoidRootPart")
        if not root or not hrp then return end
        local range = tonumber(cfg({"Ragebot","SlingBypass","AttackRange"}, 8)) or 8
        local cd = tonumber(cfg({"Ragebot","SlingBypass","ShotCooldown"}, 0.05)) or 0.05
        local now = tick()
        if (root.Position - hrp.Position).Magnitude <= range and now - (slingLastShot or 0) > cd then
            slingLastShot = now
            pcall(function() tool:Activate() end)
        end
    end

    local function startSling()
        if slingConn then slingConn:Disconnect() end
        if slingRenderConn then slingRenderConn:Disconnect() end
        slingOrbAng, slingHoverT, slingLastShot, slingLastRush = 0, 0, 0, 0
        slingFollowPos, slingRealCF = nil, nil

        if cfg({"Ragebot","SlingBypass","HideAvatar"}, true) then
            hideAvatar()
            task.spawn(function()
                while featureOn("SlingBypass") do
                    hideAvatar()
                    task.wait(0.25)
                end
            end)
        end

        slingConn = RunService.Heartbeat:Connect(function(dt)
            if not featureOn("SlingBypass") then return end
            local root = getRoot()
            if not root then return end
            slingRealCF = root.CFrame
            local mode = tostring(cfg({"Ragebot","SlingBypass","Mode"}, "Follow") or "Follow")
            local tmode = tostring(cfg({"Ragebot","SlingBypass","TargetMode"}, "Closest") or "Closest")
            local target = getTarget(tmode)
            local followDist = tonumber(cfg({"Ragebot","SlingBypass","FollowDistance"}, 2)) or 2
            local followH = tonumber(cfg({"Ragebot","SlingBypass","FollowHeight"}, 2)) or 2
            local stickH = tonumber(cfg({"Ragebot","SlingBypass","StickHeight"}, 2)) or 2
            local orbitR = tonumber(cfg({"Ragebot","SlingBypass","OrbitRadius"}, 5)) or 5
            local orbitS = tonumber(cfg({"Ragebot","SlingBypass","OrbitSpeed"}, 200)) or 200
            local orbitH = tonumber(cfg({"Ragebot","SlingBypass","OrbitHeight"}, 0)) or 0
            local useVel = cfg({"Ragebot","SlingBypass","UseTargetVel"}, true)
            local autoShoot = cfg({"Ragebot","SlingBypass","AutoShoot"}, true)
            local followLerp = tonumber(cfg({"Ragebot","SlingBypass","FollowLerp"}, 0.5)) or 0.5
            local followLead = tonumber(cfg({"Ragebot","SlingBypass","FollowLead"}, 0.15)) or 0.15
            local followPredict = cfg({"Ragebot","SlingBypass","FollowPredict"}, true)
            local stalkDist = tonumber(cfg({"Ragebot","SlingBypass","StalkDistance"}, 6)) or 6
            local stalkH = tonumber(cfg({"Ragebot","SlingBypass","StalkHeight"}, 3)) or 3
            local stalkBehind = cfg({"Ragebot","SlingBypass","StalkBehind"}, true)
            local hoverH = tonumber(cfg({"Ragebot","SlingBypass","HoverHeight"}, 8)) or 8
            local randR = tonumber(cfg({"Ragebot","SlingBypass","RandomRadius"}, 8)) or 8

            if mode == "Visual" then
                -- visual handled in RenderStepped
                return
            end
            if not target or not target.Character then return end
            local tHrp = target.Character:FindFirstChild("HumanoidRootPart")
            if not tHrp then return end
            local tVel = useVel and (tHrp.AssemblyLinearVelocity or Vector3.zero) or Vector3.zero

            if mode == "Follow" then
                local tPos = tHrp.Position
                if followPredict then tPos = predictPos(tHrp, followLead) end
                local desired = tPos + Vector3.new(0, followH, 0) - tHrp.CFrame.LookVector * followDist
                if not slingFollowPos then slingFollowPos = root.Position end
                local alpha = math.min(1, 1 - (1 - followLerp) ^ (dt * 60))
                slingFollowPos = slingFollowPos:Lerp(desired, alpha)
                tpTo(slingFollowPos, tVel)
            elseif mode == "Stalk" then
                local offset
                if stalkBehind then
                    offset = tHrp.CFrame.LookVector * -stalkDist + Vector3.new(0, stalkH, 0)
                else
                    offset = tHrp.CFrame.LookVector * stalkDist + Vector3.new(0, stalkH, 0)
                end
                local desired = tHrp.Position + offset
                if not slingFollowPos then slingFollowPos = root.Position end
                local alpha = math.min(1, 1 - (1 - followLerp) ^ (dt * 60))
                slingFollowPos = slingFollowPos:Lerp(desired, alpha)
                tpTo(slingFollowPos, tVel)
            elseif mode == "Hover" then
                slingHoverT = (slingHoverT or 0) + dt
                local bob = math.sin(slingHoverT * 4) * 1
                local desired = tHrp.Position + Vector3.new(0, hoverH + bob, 0)
                if not slingFollowPos then slingFollowPos = root.Position end
                local alpha = math.min(1, 1 - (1 - followLerp) ^ (dt * 60))
                slingFollowPos = slingFollowPos:Lerp(desired, alpha)
                tpTo(slingFollowPos, tVel)
            elseif mode == "Rush" then
                local now = tick()
                if now - (slingLastRush or 0) < 0.01 then return end
                slingLastRush = now
                local predicted = predictPos(tHrp, 0.05)
                for i = 1, 5 do
                    local jx = (math.random() - 0.5) * 2
                    local jz = (math.random() - 0.5) * 2
                    tpTo(predicted + Vector3.new(jx, stickH, jz), tVel)
                end
            elseif mode == "Stick" then
                tpTo(tHrp.Position + Vector3.new(0, stickH, 0), tVel)
            elseif mode == "OrbitTarget" then
                slingOrbAng = (slingOrbAng + math.rad(orbitS) * dt) % (2 * math.pi)
                local off = Vector3.new(math.cos(slingOrbAng) * orbitR, orbitH, math.sin(slingOrbAng) * orbitR)
                tpTo(tHrp.Position + off, tVel)
            elseif mode == "RandomAroundTarget" then
                local a = math.random() * 2 * math.pi
                tpTo(tHrp.Position + Vector3.new(math.cos(a) * randR, stickH, math.sin(a) * randR), tVel)
            end

            if autoShoot then doAutoShoot(target) end
        end)

        slingRenderConn = RunService.RenderStepped:Connect(function()
            if not featureOn("SlingBypass") then return end
            local mode = tostring(cfg({"Ragebot","SlingBypass","Mode"}, "Follow") or "Follow")
            local root = getRoot()
            if root and mode == "Visual" then
                root.CFrame = CFrame.new(0, 0, 0)
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end
        end)
    end

    local function stopSling()
        if slingConn then slingConn:Disconnect(); slingConn = nil end
        if slingRenderConn then slingRenderConn:Disconnect(); slingRenderConn = nil end
        slingFollowPos, slingRealCF = nil, nil
        if avatarHidden then restoreAvatar() end
    end

    local slingWasOn = false
    RunService.Heartbeat:Connect(function()
        local on = featureOn("SlingBypass")
        if on and not slingWasOn then startSling() end
        if not on and slingWasOn then stopSling() end
        slingWasOn = on
    end)

    ----------------------------------------------------------------
    -- Dagger Bypass (MeowwCL exact)
    ----------------------------------------------------------------
    do
        local hookfunction_ = K.fn("hookfunction")
        local newcclosure_ = K.fn("newcclosure") or function(f) return f end
        if hookfunction_ then
            pcall(function()
                local oldFireServer
                oldFireServer = hookfunction_(Instance.new("RemoteEvent").FireServer, newcclosure_(function(self, ...)
                    if not checkcaller() and featureOn("DaggerBypass") then
                        local n = tostring(self and self.Name or ""):lower()
                        local parts = {}
                        for i = 1, select("#", ...) do parts[i] = tostring(select(i, ...)) end
                        local a = table.concat(parts, " "):lower()
                        if (n:find("dagger") or n:find("knife") or n:find("throw") or n:find("blade"))
                            and not (a:find(LocalPlayer.Name:lower()) or a:find("owner")) then
                            return
                        end
                    end
                    return oldFireServer(self, ...)
                end))
            end)
            pcall(function()
                local oldFireServer
                oldFireServer = hookfunction_(Instance.new("UnreliableRemoteEvent").FireServer, newcclosure_(function(self, ...)
                    if not checkcaller() and featureOn("DaggerBypass") then
                        local n = tostring(self and self.Name or ""):lower()
                        local parts = {}
                        for i = 1, select("#", ...) do parts[i] = tostring(select(i, ...)) end
                        local a = table.concat(parts, " "):lower()
                        if (n:find("dagger") or n:find("knife") or n:find("throw") or n:find("blade"))
                            and not (a:find(LocalPlayer.Name:lower()) or a:find("owner")) then
                            return
                        end
                    end
                    return oldFireServer(self, ...)
                end))
            end)
        end
    end

    ----------------------------------------------------------------
    -- Expand Hitbox (Lua X range extender)
    ----------------------------------------------------------------
    local originalParts = {}
    local rangeConn
    local originalRaycast

    local function applyHitbox(plr, size, transparency, safeDist, useSafe)
        if not plr.Character then return end
        local root = getRoot()
        if useSafe and root then
            local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
            if hrp and (hrp.Position - root.Position).Magnitude < safeDist then return end
        end
        -- agrandar todas las partes para que cualquier disparo cerca cuente
        for _, part in ipairs(plr.Character:GetDescendants()) do
            if part:IsA("BasePart") then
                if not originalParts[part] then
                    originalParts[part] = {
                        size = part.Size,
                        transparency = part.Transparency,
                        cancollide = part.CanCollide,
                        canquery = part.CanQuery,
                    }
                end
                pcall(function()
                    local s = size
                    -- cabeza un poco mas grande para headshot
                    if part.Name == "Head" then s = size * 1.15 end
                    part.Size = Vector3.new(s, s, s)
                    part.Transparency = transparency
                    part.CanCollide = false
                    part.CanQuery = true
                    part.Massless = true
                end)
            end
        end
    end

    local function clearHitbox(plr)
        if not plr.Character then return end
        for _, part in ipairs(plr.Character:GetDescendants()) do
            if part:IsA("BasePart") then
                local orig = originalParts[part]
                if orig then
                    pcall(function()
                        part.Size = orig.size
                        part.Transparency = orig.transparency
                        part.CanCollide = orig.cancollide
                        part.Massless = false
                    end)
                end
            end
        end
    end

    local function clearAllHitboxes()
        for _, p in ipairs(Players:GetPlayers()) do clearHitbox(p) end
        originalParts = {}
    end

    local function startExpand()
        if rangeConn then rangeConn:Disconnect() end
        -- optional raycast patch
        if cfg({"Ragebot","ExpandHitbox","PatchRaycast"}, true) and not originalRaycast then
            pcall(function()
                originalRaycast = workspace.Raycast
                local old = originalRaycast
                workspace.Raycast = function(self, origin, direction, params)
                    if featureOn("ExpandHitbox") then
                        local range = 5e12
                        direction = direction.Unit * range
                    end
                    return old(self, origin, direction, params)
                end
            end)
        end
        rangeConn = RunService.Heartbeat:Connect(function()
            if not featureOn("ExpandHitbox") then return end
            local size = tonumber(cfg({"Ragebot","ExpandHitbox","HitboxSize"}, 80)) or 80
            local tr = tonumber(cfg({"Ragebot","ExpandHitbox","Transparency"}, 0.7)) or 0.7
            local maxE = tonumber(cfg({"Ragebot","ExpandHitbox","MaxEnemies"}, 30)) or 30
            local teamCheck = cfg({"Ragebot","ExpandHitbox","TeamCheck"}, true)
            local useSafe = cfg({"Ragebot","ExpandHitbox","SafeDistance"}, false)
            local safeDist = tonumber(cfg({"Ragebot","ExpandHitbox","SafeDist"}, 5)) or 5
            local count = 0
            for _, p in ipairs(Players:GetPlayers()) do
                if count >= maxE then break end
                if p ~= LocalPlayer then
                    if teamCheck and LocalPlayer.Team and p.Team == LocalPlayer.Team then
                        -- skip teammate
                    else
                        applyHitbox(p, size, tr, safeDist, useSafe)
                        count = count + 1
                    end
                end
            end
        end)
    end

    local function stopExpand()
        if rangeConn then rangeConn:Disconnect(); rangeConn = nil end
        clearAllHitboxes()
    end

    local expandWasOn = false
    RunService.Heartbeat:Connect(function()
        local on = featureOn("ExpandHitbox")
        if on and not expandWasOn then startExpand() end
        if not on and expandWasOn then stopExpand() end
        expandWasOn = on
    end)

    ----------------------------------------------------------------
    -- Anti Aim (Lua X)
    ----------------------------------------------------------------
    local aaConn
    local aaAngAcc, aaMicroTimer, aaRollAcc, aaBreatheAcc = 0, 0, 0, 0

    local function startAA()
        if aaConn then aaConn:Disconnect() end
        aaAngAcc, aaMicroTimer, aaRollAcc, aaBreatheAcc = 0, 0, 0, 0
        aaConn = RunService.Heartbeat:Connect(function(dt)
            if not featureOn("AntiAim") then return end
            local root = getRoot()
            if not root then return end
            local mode = tostring(cfg({"Ragebot","AntiAim","Mode"}, "RandomSpin") or "RandomSpin")
            local speed = tonumber(cfg({"Ragebot","AntiAim","Speed"}, 5000)) or 5000
            local pitchA = tonumber(cfg({"Ragebot","AntiAim","PitchAngle"}, 45)) or 45
            local yawA = tonumber(cfg({"Ragebot","AntiAim","YawAngle"}, 45)) or 45
            local jitterPitch = cfg({"Ragebot","AntiAim","JitterPitch"}, true)
            local jitterYaw = cfg({"Ragebot","AntiAim","JitterYaw"}, true)
            local staticYaw = tonumber(cfg({"Ragebot","AntiAim","StaticYaw"}, 90)) or 90
            local staticPitch = tonumber(cfg({"Ragebot","AntiAim","StaticPitch"}, 0)) or 0
            local customYaw = tonumber(cfg({"Ragebot","AntiAim","CustomYaw"}, 180)) or 180
            local customPitch = tonumber(cfg({"Ragebot","AntiAim","CustomPitch"}, 0)) or 0

            aaAngAcc = (aaAngAcc + speed * dt) % 360
            local extraYaw, extraPitch, rollAngle = 0, 0, 0

            local yaw, pitch = 0, 0
            if mode == "Spin" or mode == "RandomSpin" then
                yaw = aaAngAcc
                pitch = jitterPitch and ((math.random() - 0.5) * pitchA * 2) or 0
            elseif mode == "Jitter" then
                yaw = jitterYaw and ((math.random() - 0.5) * yawA * 2) or 0
                pitch = jitterPitch and ((math.random() - 0.5) * pitchA * 2) or 0
            elseif mode == "Static" then
                yaw = staticYaw
                pitch = staticPitch
            elseif mode == "Up" then
                pitch = -89
                yaw = aaAngAcc
            elseif mode == "Down" then
                pitch = 89
                yaw = aaAngAcc
            elseif mode == "Side" then
                yaw = staticYaw + 90
                pitch = staticPitch
            elseif mode == "Custom" then
                yaw = customYaw + aaAngAcc * 0 -- hold custom
                pitch = customPitch
                yaw = customYaw
            else
                yaw = aaAngAcc
            end

            pcall(function()
                root.CFrame = CFrame.new(root.Position) * CFrame.Angles(math.rad(pitch + extraPitch), math.rad(yaw + extraYaw), rollAngle)
            end)
        end)
    end

    local function stopAA()
        if aaConn then aaConn:Disconnect(); aaConn = nil end
    end

    local aaWasOn = false
    RunService.Heartbeat:Connect(function()
        local on = featureOn("AntiAim")
        if on and not aaWasOn then startAA() end
        if not on and aaWasOn then stopAA() end
        aaWasOn = on
    end)

    ----------------------------------------------------------------
    -- Translocation (Lua X simplified full options)
    ----------------------------------------------------------------
    local translocConn, translocPreRender, translocRealCF
    local translocAcc = 0

    local function startTransloc()
        if translocConn then translocConn:Disconnect() end
        if translocPreRender then translocPreRender:Disconnect() end
        translocRealCF = nil
        translocAcc = 0

        translocPreRender = RunService.PreRender:Connect(function()
            if not featureOn("Translocation") then return end
            local root = getRoot()
            if not root or not translocRealCF then return end
            if cfg({"Ragebot","Translocation","SnapBack"}, true) then
                pcall(function()
                    root.CFrame = translocRealCF
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end)
            end
        end)

        translocConn = RunService.Heartbeat:Connect(function(dt)
            if not featureOn("Translocation") then return end
            local root = getRoot()
            if not root then return end
            translocRealCF = root.CFrame
            local freq = math.max(1, tonumber(cfg({"Ragebot","Translocation","Frequency"}, 256)) or 256)
            local interval = 1 / freq
            translocAcc = translocAcc + dt
            if translocAcc < interval then return end
            translocAcc = translocAcc % interval

            local dist = tonumber(cfg({"Ragebot","Translocation","OffsetDist"}, 100)) or 100
            local offY = tonumber(cfg({"Ragebot","Translocation","OffsetY"}, 0)) or 0
            local mode = tostring(cfg({"Ragebot","Translocation","OffsetMode"}, "Ahead") or "Ahead")
            local jitter = cfg({"Ragebot","Translocation","Jitter"}, false)
            local fakeVel = cfg({"Ragebot","Translocation","FakeVel"}, true)

            local look = root.CFrame.LookVector
            local right = root.CFrame.RightVector
            local offset = Vector3.zero
            if mode == "Ahead" then
                offset = look * dist
            elseif mode == "Behind" then
                offset = -look * dist
            elseif mode == "Up" then
                offset = Vector3.new(0, dist, 0)
            elseif mode == "Down" then
                offset = Vector3.new(0, -dist, 0)
            elseif mode == "Side" then
                offset = right * dist
            else -- Random
                local a = math.random() * 2 * math.pi
                offset = Vector3.new(math.cos(a) * dist, 0, math.sin(a) * dist)
            end
            offset = offset + Vector3.new(0, offY, 0)
            if jitter then
                offset = offset + Vector3.new((math.random()-0.5)*dist*0.2, (math.random()-0.5)*10, (math.random()-0.5)*dist*0.2)
            end

            local newPos = root.Position + offset
            local vel = fakeVel and (offset.Unit * 1e6) or Vector3.zero
            pcall(function()
                root.CFrame = CFrame.new(newPos, newPos + look)
                root.AssemblyLinearVelocity = vel
            end)
        end)
    end

    local function stopTransloc()
        if translocConn then translocConn:Disconnect(); translocConn = nil end
        if translocPreRender then translocPreRender:Disconnect(); translocPreRender = nil end
        -- restore real pos once
        local root = getRoot()
        if root and translocRealCF then
            pcall(function()
                root.CFrame = translocRealCF
                root.AssemblyLinearVelocity = Vector3.zero
            end)
        end
        translocRealCF = nil
    end

    local translocWasOn = false
    RunService.Heartbeat:Connect(function()
        local on = featureOn("Translocation")
        if on and not translocWasOn then startTransloc() end
        if not on and translocWasOn then stopTransloc() end
        translocWasOn = on
    end)

    

    ----------------------------------------------------------------
    -- Fake Position: under YOUR floor at lock XZ (no random TP)
    ----------------------------------------------------------------
    local fakeHB, fakePre
    local lockXZ, lockFloorY, lockLook
    local locked = false
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local function fpEnabled()
        return featureOn("FakePosition")
    end

    local function sampleFloor(root)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        local char = LocalPlayer.Character
        if char then params.FilterDescendantsInstances = { char } end
        local origin = root.Position + Vector3.new(0, 40, 0)
        local hit = workspace:Raycast(origin, Vector3.new(0, -250, 0), params)
        if hit then return hit.Position.Y end
        return root.Position.Y
    end

    local function hold()
        if not fpEnabled() then return end
        local root = getRoot()
        if not root then return end
        if not locked or not lockXZ then
            lockXZ = Vector3.new(root.Position.X, 0, root.Position.Z)
            lockFloorY = sampleFloor(root)
            lockLook = root.CFrame.LookVector
            locked = true
        end
        local depth = tonumber(cfg({"Ragebot", "FakePosition", "OffsetY"}, -6)) or -6
        depth = math.abs(depth)
        if depth < 2 then depth = 4 end
        if depth > 20 then depth = 20 end
        local offX = tonumber(cfg({"Ragebot", "FakePosition", "OffsetX"}, 0)) or 0
        local offZ = tonumber(cfg({"Ragebot", "FakePosition", "OffsetZ"}, 0)) or 0
        local pitch = tonumber(cfg({"Ragebot", "FakePosition", "Pitch"}, 90)) or 90
        local panic = cfg({"Ragebot", "FakePosition", "PanicX"}, false) == true
        local px = 0
        if panic then
            local pMin = tonumber(cfg({"Ragebot", "FakePosition", "PanicMin"}, -10)) or -10
            local pMax = tonumber(cfg({"Ragebot", "FakePosition", "PanicMax"}, 10)) or 10
            local span = math.max(0.5, pMax - pMin)
            local t = tick() * 12
            local tri = t % 2
            if tri > 1 then tri = 2 - tri end
            px = pMin + tri * span
        end
        local pos = Vector3.new(lockXZ.X + offX + px, lockFloorY - depth, lockXZ.Z + offZ)
        local look = lockLook or Vector3.new(0, 0, -1)
        local flat = Vector3.new(look.X, 0, look.Z)
        if flat.Magnitude < 0.05 then flat = Vector3.new(0, 0, -1) end
        flat = flat.Unit
        local yaw = math.atan2(-flat.X, -flat.Z)
        local cf = CFrame.new(pos) * CFrame.Angles(0, yaw, 0) * CFrame.Angles(math.rad(pitch), 0, 0)
        pcall(function()
            root.Anchored = true
            root.CFrame = cf
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            local hum = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
            if hum then hum.PlatformStand = true end
        end)
        -- light godmode while FP on
        pcall(function()
            local char = LocalPlayer.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health < hum.MaxHealth then hum.Health = hum.MaxHealth end
            if not char:FindFirstChild("KyvweerFP_FF") then
                local ff = Instance.new("ForceField")
                ff.Name = "KyvweerFP_FF"
                ff.Visible = false
                ff.Parent = char
            end
        end)
    end

    local function startFakePos()
        if fakeHB then pcall(function() fakeHB:Disconnect() end) end
        if fakePre then pcall(function() fakePre:Disconnect() end) end
        fakeHB, fakePre = nil, nil
        locked = false
        lockXZ, lockFloorY, lockLook = nil, nil, nil
        local root = getRoot()
        if root then
            lockXZ = Vector3.new(root.Position.X, 0, root.Position.Z)
            lockFloorY = sampleFloor(root)
            lockLook = root.CFrame.LookVector
            locked = true
        end
        -- only Heartbeat (no PreRender spam = less lag)
        fakeHB = RunService.Heartbeat:Connect(hold)
    end

    local function stopFakePos()
        if fakeHB then pcall(function() fakeHB:Disconnect() end); fakeHB = nil end
        if fakePre then pcall(function() fakePre:Disconnect() end); fakePre = nil end
        local root = getRoot()
        if root then
            pcall(function()
                local x = lockXZ and lockXZ.X or root.Position.X
                local z = lockXZ and lockXZ.Z or root.Position.Z
                local y = (lockFloorY or root.Position.Y) + 3.2
                local look = lockLook or Vector3.new(0, 0, -1)
                local flat = Vector3.new(look.X, 0, look.Z)
                if flat.Magnitude < 0.05 then flat = Vector3.new(0, 0, -1) end
                flat = flat.Unit
                root.CFrame = CFrame.new(Vector3.new(x, y, z), Vector3.new(x, y, z) + flat)
                root.Anchored = false
                root.AssemblyLinearVelocity = Vector3.zero
                local hum = root.Parent and root.Parent:FindFirstChildOfClass("Humanoid")
                if hum then
                    hum.PlatformStand = false
                    pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end)
                end
                local char = LocalPlayer.Character
                if char then
                    local ff = char:FindFirstChild("KyvweerFP_FF")
                    if ff then ff:Destroy() end
                end
            end)
        end
        locked = false
        lockXZ, lockFloorY, lockLook = nil, nil, nil
    end

    -- force OFF on load
    pcall(function()
        if store and store.Data and store.Data.Ragebot and store.Data.Ragebot.FakePosition then
            store.Data.Ragebot.FakePosition.Enabled = false
            if type(store.Data.Ragebot.FakePosition.Keybind) == "table" then
                store.Data.Ragebot.FakePosition.Keybind.State = false
            end
        end
    end)

    local wasOn = false
    RunService.Heartbeat:Connect(function()
        local on = fpEnabled()
        if on and not wasOn then startFakePos() end
        if not on and wasOn then stopFakePos() end
        wasOn = on
    end)

    pcall(function()
        LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.25)
            locked = false
            if fpEnabled() then stopFakePos(); startFakePos() end
        end)
    end)

----------------------------------------------------------------
    -- UE-style Ragebot combat + perfected Void Spam
    ----------------------------------------------------------------
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer
    local UIS = game:GetService("UserInputService")
    local VirtualInputManager = game:GetService("VirtualInputManager")

    local function rageOn()
        return featureOn("Ragebot")
    end

    local function voidOn()
        return featureOn("VoidSpam")
    end

    local function isEnemy(p)
        if not p or p == LocalPlayer then return false end
        if not p.Character then return false end
        local hum = p.Character:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return false end
        local myTeam = LocalPlayer.Team
        if myTeam and p.Team and myTeam == p.Team then return false end
        return true
    end

    -- Sleepy-style target: Lowest Health / Distance / FOV, always Head hitbox
    local function getClosestEnemy()
        local root = getRoot()
        if not root then return nil end
        local cam = workspace.CurrentCamera
        local method = tostring(cfg({"Ragebot", "TargetPriority"}, "Lowest Health") or "Lowest Health")
        local fovR = tonumber(cfg({"Ragebot", "FOV"}, 200)) or 200
        local useFov = cfg({"Ragebot", "UseFOV"}, false)
        local center = cam and (cam.ViewportSize / 2) or Vector2.new(0, 0)
        local best, bestScore, bestD = nil, math.huge, math.huge

        for _, p in ipairs(Players:GetPlayers()) do
            if isEnemy(p) then
                local char = p.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                local head = char and (char:FindFirstChild("Head") or char:FindFirstChild("head"))
                if hrp and hum and hum.Health > 0 and not char:FindFirstChildOfClass("ForceField") then
                    local d = (root.Position - hrp.Position).Magnitude
                    local fovDist = 0
                    local okFov = true
                    if cam then
                        local scr, on = cam:WorldToViewportPoint(hrp.Position)
                        fovDist = (Vector2.new(scr.X, scr.Y) - center).Magnitude
                        if useFov and (not on or fovDist > fovR) then
                            okFov = false
                        end
                    end
                    if okFov then
                        local score
                        if method == "Distance" or method == "Closest Distance" then
                            score = d
                        elseif method == "Crosshair" or method == "FOV" then
                            score = fovDist
                        elseif method == "FOV - Lowest Health" then
                            score = (hum.Health * 2) + fovDist
                        else
                            score = hum.Health
                        end
                        if head then score = score - 5 end
                        if score < bestScore then
                            bestScore = score
                            bestD = d
                            best = p
                        end
                    end
                end
            end
        end
        return best, bestD
    end

    local function equipPreferredWeapon()
        -- Never auto-equip: user chooses weapons freely while rage is on
        local char = LocalPlayer.Character
        if not char then return nil end
        return char:FindFirstChildOfClass("Tool")
    end

    -- PREMIUM HEADSHOT ENGINE
    local function getHead(character)
        if not character then return nil end
        local h = character:FindFirstChild("Head") or character:FindFirstChild("head")
        if h and h:IsA("BasePart") then return h end
        return nil
    end

    local function headPosition(character)
        local head = getHead(character)
        if head then return head.Position, head end
        local hrp = character and character:FindFirstChild("HumanoidRootPart")
        if hrp then return hrp.Position + Vector3.new(0, 1.65, 0), nil end
        return nil, nil
    end

    local function predictHead(character)
        local headPos, head = headPosition(character)
        if not headPos then return nil, nil end
        local hrp = character:FindFirstChild("HumanoidRootPart")
        local vel = hrp and hrp.AssemblyLinearVelocity or Vector3.zero
        -- light prediction for moving targets
        local lead = tonumber(cfg({"Ragebot", "HeadLead"}, 0.06)) or 0.06
        return headPos + vel * lead, head
    end

    local function aimAtHead(targetChar)
        if not targetChar then return nil, nil end
        local headPos, headPart = predictHead(targetChar)
        if not headPos then return nil, nil end
        -- NO mover camara ni personaje: permite elegir armas y desactivar el menú
        return headPart, headPos
    end

    local remoteCache, remoteCacheAt = {}, 0
    local function collectRemotes(tool)
        local now = tick()
        if now - remoteCacheAt < 2 and #remoteCache > 0 then
            return remoteCache
        end
        local sources, seen = {}, {}
        local function add(d)
            if d and not seen[d] and (d:IsA("RemoteEvent") or d:IsA("RemoteFunction")) then
                seen[d] = true
                sources[#sources + 1] = d
            end
        end
        if tool then
            for _, d in ipairs(tool:GetDescendants()) do add(d) end
        end
        local char = LocalPlayer.Character
        if char then
            for _, d in ipairs(char:GetDescendants()) do
                if d:IsA("RemoteEvent") or d:IsA("RemoteFunction") then
                    local n = d.Name:lower()
                    if n:find("fire") or n:find("shoot") or n:find("hit") or n:find("attack")
                        or n:find("bullet") or n:find("damage") or n:find("shot") then
                        add(d)
                    end
                end
            end
        end
        remoteCache, remoteCacheAt = sources, now
        return sources
    end

    local function fireToolAtHead(tool, headPart, headPos, targetChar)
        if not headPos then return end
        if tool then
            pcall(function()
                if tool.Parent ~= LocalPlayer.Character then
                    tool.Parent = LocalPlayer.Character
                end
            end)
            pcall(function() tool:Activate() end)
        end
        for _, d in ipairs(collectRemotes(tool)) do
            if d:IsA("RemoteEvent") then
                pcall(function() d:FireServer(headPos) end)
                pcall(function() d:FireServer(headPart, headPos) end)
                pcall(function() d:FireServer(targetChar, headPos) end)
            end
        end
    end

    local function doShoot(times, targetChar)
        times = math.clamp(math.floor(tonumber(times) or 1), 1, 16)
        local tool = equipPreferredWeapon()
        local headPart, headPos = aimAtHead(targetChar)
        for _ = 1, times do
            fireToolAtHead(tool, headPart, headPos, targetChar)
        end
    end

local function faceAndMoveTo(root, targetHrp, height)
        height = height or -2
        local char = targetHrp.Parent
        local headPos = select(1, headPosition(char)) or (targetHrp.Position + Vector3.new(0, 1.65, 0))
        local pos = targetHrp.Position + Vector3.new(0, height, 0)
        pcall(function()
            root.CFrame = CFrame.new(pos, headPos)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
        aimAtHead(char)
    end

    local function tpUnderEnemy(root, targetHrp)
        local under = tonumber(cfg({"Ragebot", "UnderOffset"}, -2)) or -2
        if under > 0 then under = -under end
        faceAndMoveTo(root, targetHrp, under)
    end

    -- TP to ideal headshot angle (slightly under + front of head)
    local function tpHeadshotAngle(root, targetChar)
        local headPos, head = headPosition(targetChar)
        local hrp = targetChar:FindFirstChild("HumanoidRootPart")
        if not headPos or not hrp or not root then return end
        local under = tonumber(cfg({"Ragebot", "UnderOffset"}, -2)) or -2
        if under > 0 then under = -under end
        local behind = hrp.CFrame.LookVector * -1.5
        local pos = headPos + Vector3.new(0, under, 0) + behind * 0.2
        pcall(function()
            root.CFrame = CFrame.new(pos, headPos)
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
        aimAtHead(targetChar)
    end

    ----------------------------------------------------------------
    -- Void Spam core
    ----------------------------------------------------------------
    local vsConn, vsPre, vsRS
    local vsPhase, vsPhaseEnd = "attack", 0
    local vsAngle, vsWaveT = 0, 0
    local vsRealCF, vsRealVel
    local vsSeed = { math.random(), math.random(), math.random() }

    local function vsOffset(mode, dist, dt)
        mode = mode or "Random"
        dist = math.max(50, tonumber(dist) or 2500)
        if mode == "Spiral" then
            vsAngle = vsAngle + 0.4
            return Vector3.new(math.cos(vsAngle) * dist, math.sin(vsAngle * 0.55) * dist * 0.45, math.sin(vsAngle) * dist)
        elseif mode == "Wave" then
            vsWaveT = vsWaveT + (dt or 0.016) * 9
            return Vector3.new(math.sin(vsWaveT) * dist, math.sin(vsWaveT * 1.6) * dist * 0.35, math.cos(vsWaveT * 0.85) * dist)
        elseif mode == "Chaos" then
            vsSeed[1] = (vsSeed[1] * 1664525 + 1013904223) % 1
            vsSeed[2] = (vsSeed[2] * 22695477 + 1) % 1
            vsSeed[3] = (vsSeed[3] * 214013 + 2531011) % 1
            return Vector3.new((vsSeed[1] * 2 - 1) * dist, (vsSeed[2] * 2 - 1) * dist * 0.5, (vsSeed[3] * 2 - 1) * dist)
        elseif mode == "Strobe" then
            local s = (math.floor(tick() * 24) % 2 == 0) and 1 or -1
            return Vector3.new(s * dist, s * dist * 0.25, s * dist)
        else
            -- cielo / void alto (estilo HVH del video)
            local sky = math.random(math.floor(dist * 0.35), math.floor(dist * 0.9))
            return Vector3.new(math.random(-dist, dist), sky, math.random(-dist, dist))
        end
    end

    local function stopVoidSpam()
        if vsConn then vsConn:Disconnect(); vsConn = nil end
        if vsPre then vsPre:Disconnect(); vsPre = nil end
        if vsRS then vsRS:Disconnect(); vsRS = nil end
        local root = getRoot()
        if root and vsRealCF then
            pcall(function()
                root.CFrame = vsRealCF
                if vsRealVel then root.AssemblyLinearVelocity = vsRealVel end
            end)
        end
        vsRealCF, vsRealVel = nil, nil
    end

    local function startVoidSpam()
        stopVoidSpam()
        vsPhase = "attack"
        vsPhaseEnd = tick()
        vsAngle, vsWaveT = 0, 0
        vsSeed = { math.random(), math.random(), math.random() }

        pcall(function()
            local root = getRoot()
            if root then pcall(function() end) end -- SetNetworkOwner removed (range/wall desync)
        end)

        vsConn = RunService.Heartbeat:Connect(function(dt)
            if not voidOn() then return end
            local root = getRoot()
            if not root then return end

            local attackT = math.max(0.01, tonumber(cfg({"Ragebot", "VoidSpam", "AttackTime"}, 0.01)) or 0.01)
            local hideT = math.max(0.01, tonumber(cfg({"Ragebot", "VoidSpam", "HideTime"}, 0.05)) or 0.05)
            local dist = tonumber(cfg({"Ragebot", "VoidSpam", "VoidDistance"}, 5000)) or 5000
            local mode = tostring(cfg({"Ragebot", "VoidSpam", "Mode"}, "Random") or "Random")
            local autoShoot = cfg({"Ragebot", "VoidSpam", "AutoShoot"}, true)
            local zeroVel = cfg({"Ragebot", "VoidSpam", "ZeroVel"}, true)
            local restore = cfg({"Ragebot", "VoidSpam", "RestoreClient"}, true)
            local attempts = math.clamp(tonumber(cfg({"Ragebot", "ShootAttempts"}, 12)) or 12, 1, 24)

            local now = tick()
            if now >= vsPhaseEnd then
                if vsPhase == "attack" then
                    vsPhase = "hide"
                    vsPhaseEnd = now + hideT
                else
                    vsPhase = "attack"
                    vsPhaseEnd = now + attackT
                end
            end

            -- always remember real before mutating
            if restore then
                vsRealCF = root.CFrame
                vsRealVel = root.AssemblyLinearVelocity
            end

            local target = select(1, getClosestEnemy())
            if vsPhase == "attack" then
                if target and target.Character then
                    local tHrp = target.Character:FindFirstChild("HumanoidRootPart")
                    local tHead = target.Character:FindFirstChild("Head")
                    if tHrp then
                        -- Void + Rage juntos: TP cerca de la cabeza del target y dispara
                        local aimPos = tHead and tHead.Position or (tHrp.Position + Vector3.new(0, 1.6, 0))
                        pcall(function()
                            local back = (root.Position - aimPos)
                            if back.Magnitude < 1 then back = Vector3.new(0, 0, 1) end
                            back = back.Unit
                            -- un poco detras/arriba de la cabeza para hitreg
                            root.CFrame = CFrame.new(aimPos + Vector3.new(0, 2, 0) + back * 3, aimPos)
                        end)
                        aimAtHead(target.Character)
                        if zeroVel then
                            pcall(function()
                                root.AssemblyLinearVelocity = Vector3.zero
                                root.AssemblyAngularVelocity = Vector3.zero
                            end)
                        end
                        if autoShoot or rageOn() then
                            doShoot(math.max(attempts, 12), target.Character)
                            -- multi en void (estilo clips HVH)
                            if rageOn() and cfg({"Ragebot", "MultiTarget"}, true) then
                                local n = 0
                                for _, pl in ipairs(Players:GetPlayers()) do
                                    if n >= 5 then break end
                                    if pl ~= LocalPlayer and pl ~= target and isEnemy(pl) and pl.Character then
                                        local hum = pl.Character:FindFirstChildOfClass("Humanoid")
                                        if hum and hum.Health > 0 then
                                            doShoot(math.max(attempts, 8), pl.Character)
                                            n = n + 1
                                        end
                                    end
                                end
                            end
                        end
                        -- escape knife range right after attack tick
                        if cfg({"Ragebot", "AntiKnife"}, false) then
                            local escape = tonumber(cfg({"Ragebot", "EscapeDist"}, 120)) or 120
                            pcall(function()
                                local away = Vector3.new(math.random(-1,1), 0.5, math.random(-1,1))
                                if away.Magnitude < 0.1 then away = Vector3.new(1, 0.5, 0) end
                                root.CFrame = CFrame.new(tHrp.Position + away.Unit * escape + Vector3.new(0, 35, 0))
                                root.AssemblyLinearVelocity = Vector3.zero
                            end)
                        end
                    end
                elseif rageOn() then
                    -- no target: still try shoot if rage on
                    doShoot(attempts)
                end
            else
                -- hide: void alto en el cielo (estilo HVH / Voidspam del video)
                local off = vsOffset(mode, dist, dt)
                pcall(function()
                    local base = root.Position
                    if target and target.Character then
                        local th = target.Character:FindFirstChild("HumanoidRootPart")
                        if th then base = th.Position end
                    end
                    local skyY = math.max(base.Y + math.max(dist * 0.4, 400), 500)
                    local pos = Vector3.new(base.X + off.X, skyY + math.abs(off.Y) * 0.25, base.Z + off.Z)
                    root.CFrame = CFrame.new(pos)
                    root.AssemblyLinearVelocity = Vector3.new(
                        math.random(-4000, 4000),
                        math.random(500, 4000),
                        math.random(-4000, 4000)
                    )
                    root.AssemblyAngularVelocity = Vector3.new(
                        math.random(-1500, 1500),
                        math.random(-1500, 1500),
                        math.random(-1500, 1500)
                    )
                end)
            end
        end)

        local function restoreLocal()
            if not voidOn() then return end
            if not cfg({"Ragebot", "VoidSpam", "RestoreClient"}, true) then return end
            if vsPhase == "attack" then return end -- only restore during hide so attack sticks for server
            local root = getRoot()
            if root and vsRealCF then
                pcall(function()
                    root.CFrame = vsRealCF
                    if vsRealVel then root.AssemblyLinearVelocity = vsRealVel end
                end)
            end
        end
        vsPre = RunService.PreRender:Connect(restoreLocal)
        vsRS = RunService.RenderStepped:Connect(restoreLocal)
    end

    ----------------------------------------------------------------
    -- UE Ragebot combat loop (when rage on, void spam off)
    ----------------------------------------------------------------
    local rageConn
    local function stopUERage()
        if rageConn then rageConn:Disconnect(); rageConn = nil end
    end

    local function startUERage()
        stopUERage()
        local acc = 0
        local surfaceAnchor = nil
        local underConn, underPre, underStep

        local function restoreBodyCollide()
            local char = LocalPlayer.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                pcall(function()
                    hum.PlatformStand = false
                end)
            end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp then
                pcall(function()
                    hrp.Anchored = false
                end)
            end
        end

        local function forceUnderMap()
            if not rageOn() or not cfg({"Ragebot", "StayUnderMap"}, false) then
                if surfaceAnchor ~= nil then
                    surfaceAnchor = nil
                    restoreBodyCollide()
                end
                return
            end
            -- si Void Spam esta on, el void controla la posicion (HVH cielo)
            if voidOn and voidOn() then
                return
            end
            local root = getRoot()
            if not root then return end
            local char = LocalPlayer.Character
            local depth = tonumber(cfg({"Ragebot", "UnderMapDepth"}, 6)) or 6
            if depth < 3 then depth = 3 end
            if depth > 30 then depth = 30 end

            -- floor plane from raycast (or last known surface Y)
            local floorY = surfaceAnchor and surfaceAnchor.Y or root.Position.Y
            pcall(function()
                local origin = root.Position + Vector3.new(0, 50, 0)
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                params.FilterDescendantsInstances = { char }
                local hit = workspace:Raycast(origin, Vector3.new(0, -200, 0), params)
                if hit then
                    floorY = hit.Position.Y
                end
            end)

            -- XZ movement under the floor (always allowed)
            local x, z = root.Position.X, root.Position.Z
            if surfaceAnchor then
                x, z = surfaceAnchor.X, surfaceAnchor.Z
            end
            local walk = cfg({"Ragebot", "UnderMapWalk"}, false)
            if walk ~= false then
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if hum then
                    pcall(function()
                        hum.JumpPower = 0
                        hum.JumpHeight = 0
                        if hum.UseJumpPower ~= nil then hum.UseJumpPower = true end
                    end)
                    if hum.MoveDirection.Magnitude > 0 then
                        local spd = math.max(hum.WalkSpeed, 16)
                        x = x + hum.MoveDirection.X * spd * 0.03
                        z = z + hum.MoveDirection.Z * spd * 0.03
                    end
                end
            end

            surfaceAnchor = Vector3.new(x, floorY, z)
            -- locked under floor: never surface, never poke head up
            local underPos = Vector3.new(x, floorY - depth, z)
            pcall(function()
                root.CFrame = CFrame.new(underPos)
                root.AssemblyLinearVelocity = Vector3.zero
                root.AssemblyAngularVelocity = Vector3.zero
            end)

            if char then
                for _, p in ipairs(char:GetDescendants()) do
                    if p:IsA("BasePart") then
                        p.CanCollide = false
                        pcall(function()
                            p.AssemblyLinearVelocity = Vector3.zero
                        end)
                    end
                end
            end
        end

        -- force under map on every frame pipeline so it ALWAYS applies
        -- solo Heartbeat (menos lag); no PreRender/Stepped
        underConn = RunService.Heartbeat:Connect(forceUnderMap)
        underPre, underStep = nil, nil

        -- keep refs for stop
        local oldStop = stopUERage
        stopUERage = function()
            if underConn then underConn:Disconnect(); underConn = nil end
            if underPre then underPre:Disconnect(); underPre = nil end
            if underStep then underStep:Disconnect(); underStep = nil end
            if rageConn then rageConn:Disconnect(); rageConn = nil end
            surfaceAnchor = nil
            pcall(restoreBodyCollide)
        end

        rageConn = RunService.Heartbeat:Connect(function(dt)
            if not rageOn() then return end
            if voidOn() then return end
            local root = getRoot()
            if not root then return end

            -- under map at most once per tick
            if cfg({"Ragebot", "StayUnderMap"}, false) then
                forceUnderMap()
            end

            acc = acc + dt
            local stability = tonumber(cfg({"Ragebot", "Stability"}, 0.05)) or 0.05
            -- 0.05s cycles — strong but no lag
            if acc < math.max(0.04, stability) then return end
            acc = 0

            local candidates = {}
            local cam = workspace.CurrentCamera
            local method = tostring(cfg({"Ragebot", "TargetPriority"}, "Lowest Health") or "Lowest Health")
            local myPos = root.Position
            for _, p in ipairs(Players:GetPlayers()) do
                if isEnemy(p) then
                    local char = p.Character
                    if char then
                        local hrp = char:FindFirstChild("HumanoidRootPart")
                        local hum = char:FindFirstChildOfClass("Humanoid")
                        local head = char:FindFirstChild("Head")
                        if hrp and hum and hum.Health > 0 and head then
                            local d = (myPos - hrp.Position).Magnitude
                            if d < 2000 then
                                local score = hum.Health
                                if method == "Distance" then score = d
                                elseif method == "Crosshair" and cam then
                                    local sp, onScreen = cam:WorldToViewportPoint(head.Position)
                                    if onScreen then
                                        score = (Vector2.new(sp.X, sp.Y) - cam.ViewportSize / 2).Magnitude
                                    else
                                        score = d + 10000
                                    end
                                end
                                table.insert(candidates, { p = p, char = char, hrp = hrp, head = head, score = score })
                            end
                        end
                    end
                end
            end
            table.sort(candidates, function(a, b) return a.score < b.score end)
            if #candidates == 0 then return end

            local multi = cfg({"Ragebot", "MultiTarget"}, true)
            local maxT = multi and math.min(#candidates, 3) or 1
            local attempts = math.clamp(math.floor(tonumber(cfg({"Ragebot", "ShootAttempts"}, 12)) or 12), 1, 20)
            local frames = math.clamp(math.floor(tonumber(cfg({"Ragebot", "ShootFrames"}, 2)) or 2), 1, 4)
            local stayUnder = cfg({"Ragebot", "StayUnderMap"}, false)
            local savedCF = root.CFrame

            for ti = 1, maxT do
                local t = candidates[ti]
                local headPos = t.head and t.head.Position or (t.hrp.Position + Vector3.new(0, 1.6, 0))
                -- close snap for hitreg (one position, no spam)
                pcall(function()
                    local look = (headPos - root.Position)
                    if look.Magnitude < 0.1 then look = Vector3.new(0, 0, -1) end
                    local pos = headPos + Vector3.new(0, 0.15, 0) - look.Unit * 2.2
                    root.CFrame = CFrame.new(pos, headPos)
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end)
                aimAtHead(t.char)
                doShoot(attempts * frames, t.char)
            end

            if stayUnder then
                forceUnderMap()
            else
                -- don't yank back to old CF every tick (causes lag/rubberband) — only if far
                pcall(function()
                    if (root.Position - savedCF.Position).Magnitude > 80 then
                        root.CFrame = savedCF
                        root.AssemblyLinearVelocity = Vector3.zero
                    end
                end)
            end

            if cfg({"Ragebot", "SwapWhenEmpty"}, true) then
                local tool = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Tool")
                if tool then
                    local ammo = tool:FindFirstChild("Ammo") or tool:FindFirstChild("ammo")
                    if ammo and ((typeof(ammo) == "Instance" and ammo:IsA("NumberValue") and ammo.Value <= 0) or (type(ammo) == "number" and ammo <= 0)) then
                        equipPreferredWeapon()
                    end
                end
            end
        end)
    end


    local voidWas, rageWas = false, false
    RunService.Heartbeat:Connect(function()
        local v, r = voidOn(), rageOn()
        if v and not voidWas then startVoidSpam() end
        if not v and voidWas then stopVoidSpam() end
        if r and not rageWas then startUERage() end
        if not r and rageWas then stopUERage() end
        voidWas, rageWas = v, r
    end)

    pcall(function()
        LocalPlayer.CharacterAdded:Connect(function()
            task.wait(0.35)
            if voidOn() then stopVoidSpam(); startVoidSpam() end
            if rageOn() then stopUERage(); startUERage() end
        end)
    end)



    ----------------------------------------------------------------
    -- Full invulnerability while Ragebot god is on
    -- Guns, knife, molotov, mine, subspace, explosives — multi-layer client defense
    ----------------------------------------------------------------
    do
        local healthConn, diedConn, stateConn
        local godHB, godStepped, godRS
        local oldTakeDamage, hookedHum
        local blockedNames = {
            "damage", "kill", "hit", "hurt", "bleed", "burn",
            "molotov", "mine", "subspace", "subespacial", "tripmine", "trip",
            "explod", "grenade", "rocket", "bomb", "fire", "flame",
            "projectile", "bullet", "shot", "slash", "stab", "melee",
            "takedamage", "applydamage", "humanoid"
        }

        local function godActive()
            if not rageOn() then return false end
            return cfg({"Ragebot", "AntiLegit"}, false) == true
                or cfg({"Ragebot", "GodMode"}, false) == true
        end

        local function nameLooksBad(n)
            n = string.lower(tostring(n or ""))
            for _, k in ipairs(blockedNames) do
                if n:find(k, 1, true) then return true end
            end
            return false
        end

        local function forceAlive(hum, char)
            if not hum then return end
            pcall(function()
                if hum.MaxHealth < 100 then hum.MaxHealth = 999 end
                hum.Health = hum.MaxHealth
                hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
                hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
                hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false)
                hum:SetStateEnabled(Enum.HumanoidStateType.Physics, false)
                hum:SetStateEnabled(Enum.HumanoidStateType.StrafingNoPhysics, true)
                if hum:GetState() == Enum.HumanoidStateType.Dead
                    or hum:GetState() == Enum.HumanoidStateType.Ragdoll
                    or hum:GetState() == Enum.HumanoidStateType.FallingDown then
                    hum:ChangeState(Enum.HumanoidStateType.Running)
                end
            end)
            if char then
                pcall(function()
                    for _, p in ipairs(char:GetDescendants()) do
                        if p:IsA("BasePart") then
                            -- no quitar CanCollide: evita atravesar paredes
                            p.CanTouch = false
                        end
                    end
                    local ff = char:FindFirstChildOfClass("ForceField")
                    if not ff then
                        ff = Instance.new("ForceField")
                        ff.Visible = false
                        ff.Parent = char
                    end
                end)
            end
        end

        local function escapeHazards()
            -- blink away from nearby mines / fire / subspace-like parts
            if not cfg({"Ragebot", "AntiExplosives"}, false) then return end
            local root = getRoot()
            if not root then return end
            local char = LocalPlayer.Character
            local danger = false
            pcall(function()
                for _, inst in ipairs(workspace:GetChildren()) do
                    local n = string.lower(inst.Name)
                    if nameLooksBad(n) or n:find("molotov") or n:find("mine") or n:find("subspace") or n:find("fire") then
                        local p = inst:IsA("BasePart") and inst or inst:FindFirstChildWhichIsA("BasePart", true)
                        if p and (p.Position - root.Position).Magnitude < 35 then
                            danger = true
                            break
                        end
                    end
                end
            end)
            if danger then
                pcall(function()
                    local dist = tonumber(cfg({"Ragebot", "EscapeDist"}, 120)) or 120
                    root.CFrame = root.CFrame + Vector3.new(
                        math.random(-1, 1) * dist,
                        50,
                        math.random(-1, 1) * dist
                    )
                    root.AssemblyLinearVelocity = Vector3.zero
                end)
            end
        end

        local function hookHum(hum, char)
            if not hum then return end
            if healthConn then healthConn:Disconnect() end
            if diedConn then diedConn:Disconnect() end
            if stateConn then stateConn:Disconnect() end

            pcall(function()
                if hookfunction and hum.TakeDamage then
                    pcall(function()
                        if hookedHum == hum and oldTakeDamage then return end
                        oldTakeDamage = hookfunction(hum.TakeDamage, function(self, ...)
                            if godActive() then return end
                            return oldTakeDamage(self, ...)
                        end)
                        hookedHum = hum
                    end)
                end
            end)

            forceAlive(hum, char)

            healthConn = hum.HealthChanged:Connect(function(newHp)
                if not godActive() then return end
                forceAlive(hum, LocalPlayer.Character)
                if cfg({"Ragebot", "EvadeOnDamage"}, false) ~= true then return end
                -- cualquier dano minimo: cambia de posicion al instante
                pcall(function()
                    local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if not root then return end
                    local stayUnder = cfg({"Ragebot", "StayUnderMap"}, false)
                    local depth = tonumber(cfg({"Ragebot", "UnderMapDepth"}, 80)) or 80
                    local ang = math.random() * math.pi * 2
                    local dist = 40 + math.random() * 80
                    local offset = Vector3.new(math.cos(ang) * dist, stayUnder and (-depth) or (20 + math.random() * 30), math.sin(ang) * dist)
                    root.CFrame = CFrame.new(root.Position + offset)
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                end)
            end)
            diedConn = hum.Died:Connect(function()
                if not godActive() then return end
                forceAlive(hum, LocalPlayer.Character)
                task.defer(function()
                    forceAlive(LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid"), LocalPlayer.Character)
                end)
            end)
            stateConn = hum.StateChanged:Connect(function(_, new)
                if not godActive() then return end
                if new == Enum.HumanoidStateType.Dead
                    or new == Enum.HumanoidStateType.Ragdoll
                    or new == Enum.HumanoidStateType.FallingDown then
                    forceAlive(hum, LocalPlayer.Character)
                end
            end)
        end

        local function applyChar(char)
            if not char then return end
            task.spawn(function()
                local hum = char:WaitForChild("Humanoid", 5)
                hookHum(hum, char)
            end)
        end

        if LocalPlayer.Character then applyChar(LocalPlayer.Character) end
        LocalPlayer.CharacterAdded:Connect(applyChar)

        local function tickGod()
            if not godActive() then return end
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum then forceAlive(hum, char) end
            escapeHazards()
        end

        godHB = RunService.Heartbeat:Connect(tickGod)
        godStepped = nil -- Stepped disabled (lag)
        godRS = nil -- RenderStepped god disabled (anti-lag); Heartbeat tickGod is enough

        -- Block damage / explosive related remotes & TakeDamage namecalls
        pcall(function()
            if not hookmetamethod then return end
            local old
            old = hookmetamethod(game, "__namecall", function(self, ...)
                if godActive() then
                    local method = string.lower(tostring(getnamecallmethod and getnamecallmethod() or ""))
                    if method == "takedamage" then return end
                    if method == "fireserver" or method == "invokeserver" then
                        local n = tostring(self and self.Name or "")
                        if nameLooksBad(n) then
                            local args = {...}
                            local me = LocalPlayer.Name:lower()
                            for _, a in ipairs(args) do
                                if a == LocalPlayer then return end
                                if a == LocalPlayer.Character then return end
                                if type(a) == "string" and a:lower() == me then return end
                                if typeof(a) == "Instance" and LocalPlayer.Character and a:IsDescendantOf(LocalPlayer.Character) then return end
                            end
                        end
                    end
                end
                return old(self, ...)
            end)
        end)

        -- Also block NewIndex health kills
        pcall(function()
            if not hookmetamethod then return end
            local old
            old = hookmetamethod(game, "__newindex", function(self, key, value)
                if godActive() and typeof(self) == "Instance" and self:IsA("Humanoid") and self.Parent == LocalPlayer.Character then
                    if key == "Health" and type(value) == "number" and value < self.MaxHealth then
                        return old(self, key, self.MaxHealth)
                    end
                end
                return old(self, key, value)
            end)
        end)

        if K and K.onUnload then
            K.onUnload(function()
                if healthConn then healthConn:Disconnect() end
                if diedConn then diedConn:Disconnect() end
                if stateConn then stateConn:Disconnect() end
                if godHB then godHB:Disconnect() end
                if godStepped then godStepped:Disconnect() end
                if godRS then godRS:Disconnect() end
            end)
        end
    end

