  ["trowel"] = { kind = "melee", id = "Trowel" },
  ["uzi"] = { kind = "secondary", id = "Uzi" },
  ["war horn"] = { kind = "util", id = "WarHorn" },
  ["warhorn"] = { kind = "util", id = "WarHorn" },
  ["warper"] = { kind = "secondary", id = "Warper" },
  ["warpstone"] = { kind = "util", id = "Warpstone" },
  ["wildcat"] = { kind = "primary", id = "Wildcat" },
}

local rivalsWeaponAssets = {} -- id -> getcustomasset path
local function ensureRivalsWeaponIcons()
    if next(rivalsWeaponAssets) then return rivalsWeaponAssets end
    local folder = "kyvweerrebuild/weapons"
    pcall(function()
        if isfolder and not isfolder(folder) then makefolder("kyvweerrebuild") makefolder(folder) end
    end)
    local function b64decode(data)
        local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
        data = string.gsub(data, '[^'..b..'=]', '')
        return (data:gsub('.', function(x)
            if x == '=' then return '' end
            local r, f = '', (b:find(x) - 1)
            for i = 6, 1, -1 do r = r .. (f % 2^i - f % 2^(i-1) > 0 and '1' or '0') end
            return r
        end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
            if #x ~= 8 then return '' end
            local c = 0
            for i = 1, 8 do c = c + (x:sub(i, i) == '1' and 2^(8 - i) or 0) end
            return string.char(c)
        end))
    end
    for id, b64 in pairs(RIVALS_WEAPON_B64) do
        local path = folder .. "/" .. id .. ".png"
        pcall(function()
            if writefile and (not isfile or not isfile(path)) then
                writefile(path, b64decode(b64))
            end
            local asset = nil
            if getcustomasset then asset = getcustomasset(path)
            elseif getsynasset then asset = getsynasset(path) end
            if asset then rivalsWeaponAssets[id] = asset end
        end)
    end
    return rivalsWeaponAssets
end

local function resolveRivalsWeapon(name)
    if not name then return nil end
    local n = string.lower(tostring(name))
    n = n:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
    local hit = RIVALS_WEAPON_CLASS[n]
    if hit then return hit end
    -- fuzzy contains
    for key, hit2 in pairs(RIVALS_WEAPON_CLASS) do
        if n:find(key, 1, true) or key:find(n, 1, true) then return hit2 end
    end
    return nil
end

