        hudMeta = label({Position=UDim2.fromOffset(left,36), Size=UDim2.new(1,-(left+right),0,16), Font=Enum.Font.Gotham, TextSize=13, TextColor3=Color3.fromRGB(155,158,168), TextXAlignment=Enum.TextXAlignment.Left, Text="level —  rank —  device —  streak —"})
        hudHealthWord = label({Position=UDim2.fromOffset(left,64), Size=UDim2.fromOffset(48,16), Font=Enum.Font.Gotham, TextSize=13, TextColor3=Color3.fromRGB(210,210,218), TextXAlignment=Enum.TextXAlignment.Left, Text="health"})
        hudBarBg = Instance.new("Frame")
