        hudHPNums = label({AnchorPoint=Vector2.new(1,0), Position=UDim2.new(1,-right,0,64), Size=UDim2.fromOffset(64,16), Font=Enum.Font.GothamMedium, TextSize=13, TextColor3=Color3.fromRGB(230,230,236), TextXAlignment=Enum.TextXAlignment.Right, Text="0 / 0"})
        hudDmgWord = label({Position=UDim2.fromOffset(left,90), Size=UDim2.fromOffset(90,16), Font=Enum.Font.Gotham, TextSize=13, TextColor3=Color3.fromRGB(210,210,218), TextXAlignment=Enum.TextXAlignment.Left, Text="damage ratio"})
        hudDmgVal = label({Position=UDim2.fromOffset(left+100,90), Size=UDim2.new(1,-(left+right+100),0,16), Font=Enum.Font.GothamMedium, TextSize=13, TextColor3=Color3.fromRGB(235,110,145), TextXAlignment=Enum.TextXAlignment.Left, Text="—   ▲ —   ▼ —"})
        -- Free drag anywhere (UE MakeDraggable style) — no panel needed
        local dragging = false
        local function saveFreePos()
            if not hudRoot then return end
            local abs = hudRoot.AbsolutePosition
            freeHudPos = Vector2.new(abs.X, abs.Y)
            pcall(function()
                local cam = workspace.CurrentCamera
                local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
                local g = (getgenv and getgenv()) or _G
                local store = g.Kyvweer_ReactiveStore
                if store and store.Data and store.Data.Ragebot then
                    store.Data.Ragebot.TargetHUD = store.Data.Ragebot.TargetHUD or {}
                    store.Data.Ragebot.TargetHUD.PosX = math.clamp(abs.X / math.max(vp.X, 1) * 100, 0, 100)
                    store.Data.Ragebot.TargetHUD.PosY = math.clamp(abs.Y / math.max(vp.Y, 1) * 100, 0, 100)
                    store.Data.Ragebot.TargetHUD.FreeX = abs.X
                    store.Data.Ragebot.TargetHUD.FreeY = abs.Y
                end
            end)
        end
        hudRoot.InputBegan:Connect(function(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            dragging = true
            hudRoot:SetAttribute("Dragging", true)
            local offset
            if input.UserInputType == Enum.UserInputType.Touch then
                offset = Vector2.new(input.Position.X - hudRoot.AbsolutePosition.X, input.Position.Y - hudRoot.AbsolutePosition.Y)
            else
                local m = UIS:GetMouseLocation()
                -- GetMouseLocation includes inset; AbsolutePosition is screen space with IgnoreGuiInset
                offset = Vector2.new(m.X - hudRoot.AbsolutePosition.X, m.Y - hudRoot.AbsolutePosition.Y)
            end
            task.spawn(function()
                while dragging and hudRoot do
                    local pos
                    if input.UserInputType == Enum.UserInputType.Touch and input.UserInputState ~= Enum.UserInputState.End then
                        pos = Vector2.new(input.Position.X, input.Position.Y)
                    else
                        if not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then break end
                        pos = UIS:GetMouseLocation()
                    end
                    local cam = workspace.CurrentCamera
                    local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
                    local sz = hudRoot.AbsoluteSize
                    local np = Vector2.new(
                        math.clamp(pos.X - offset.X, 0, math.max(0, vp.X - sz.X)),
                        math.clamp(pos.Y - offset.Y, 0, math.max(0, vp.Y - sz.Y))
                    )
                    hudRoot.Position = UDim2.fromOffset(np.X, np.Y)
                    RunService.RenderStepped:Wait()
                end
                dragging = false
                if hudRoot then
                    hudRoot:SetAttribute("Dragging", false)
                    saveFreePos()
                end
            end)
        end)
        UIS.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                dragging = false
            end
        end)
        pcall(function()
            local g = (getgenv and getgenv()) or _G
            local store = g.Kyvweer_ReactiveStore
            local th = store and store.Data and store.Data.Ragebot and store.Data.Ragebot.TargetHUD
            if th and th.FreeX and th.FreeY then
                freeHudPos = Vector2.new(th.FreeX, th.FreeY)
                hudRoot.Position = UDim2.fromOffset(th.FreeX, th.FreeY)
            end
        end)
        return true
    end

    local function deepFind(root, keys, depth)
        if not root or depth > 5 then return nil end
        for _, key in ipairs(keys) do
            local ok, v = pcall(function() return root:GetAttribute(key) end)
            if ok and v ~= nil and tostring(v) ~= "" then return v end
            local ch = root:FindFirstChild(key, true)
            if ch then
                if ch:IsA("ValueBase") then return ch.Value end
            end
        end
        return nil
    end

    local function getStat(plr, keys)
        if not plr then return nil end
        local v = deepFind(plr, keys, 0)
        if v ~= nil then return v end
        if plr.Character then
            v = deepFind(plr.Character, keys, 0)
            if v ~= nil then return v end
            -- overhead billboards sometimes show rank text
            for _, d in ipairs(plr.Character:GetDescendants()) do
                if d:IsA("TextLabel") or d:IsA("TextButton") then
                    local t = string.lower(d.Text or "")
                    for _, key in ipairs(keys) do
                        local k = string.lower(key)
                        if t:find(k) then
                            local num = t:match("(%d+)")
                            if num then return num end
                            local word = t:match(k .. "%s*([%w%+_]+)")
                            if word then return word end
                        end
                    end
                end
            end
        end
        for _, folderName in ipairs({"PlayerData", "Profiles", "Players", "Data", "PlayerStats", "Stats", "Replicas"}) do
            local folder = RS:FindFirstChild(folderName)
            if folder then
                local entry = folder:FindFirstChild(tostring(plr.UserId)) or folder:FindFirstChild(plr.Name)
                if entry then
                    v = deepFind(entry, keys, 0)
                    if v ~= nil then return v end
                end
            end
        end
        return nil
    end

    local function classifyName(n)
        n = string.lower(tostring(n or ""))
        if n == "" or #n < 2 then return nil end
        -- ignore body parts
        if n:find("hand") or n:find("arm") or n:find("leg") or n:find("foot") or n:find("torso") or n:find("head") or n:find("humanoid") or n:find("root") then return nil end
        if n:find("knife") or n:find("melee") or n:find("dagger") or n:find("blade") or n:find("sword") or n:find("katana") or n:find("bat") or n:find("tactical") or n:find("axe") or n:find("claw") or n:find("bayonet") then return "melee" end
        if n:find("pistol") or n:find("deagle") or n:find("secondary") or n:find("revolver") or n:find("handgun") or n:find("usp") or n:find("glock") or n:find("dual") or n:find("sidearm") or n:find("beretta") then return "secondary" end
        if n:find("grenade") or n:find("molotov") or n:find("flash") or n:find("smoke") or n:find("mine") or n:find("util") or n:find("throwable") or n:find("nade") or n:find("satchel") or n:find("c4") or n:find("he ") then return "util" end
        if n:find("rifle") or n:find("gun") or n:find("smg") or n:find("shotgun") or n:find("sniper") or n:find("ak") or n:find("m4") or n:find("weapon") or n:find("primary") or n:find("carbine") or n:find("lmg") or n:find("burst") or n:find("ar15") or n:find("vector") or n:find("mp5") or n:find("uzi") or n:find("scar") or n:find("famas") or n:find("aug") then return "primary" end
        return nil
    end

    local function weaponsOf(plr)
        local out = { primary = nil, secondary = nil, melee = nil, util = nil }
        local function set(kind, name, tex)
            if not kind or out[kind] then return end
            out[kind] = { Name = tostring(name or kind), TextureId = tostring(tex or "") }
        end
        local function consider(name, tex)
            if not name then return end
            local resolved = resolveRivalsWeapon(name)
            local kind = resolved and resolved.kind or classifyName(name)
            local id = resolved and resolved.id or name
            if kind then set(kind, id, tex) end
        end
        if not plr then return out end

        -- 1) Character tools / models / welds
        local function scanInst(inst, depth)
            if not inst or depth > 6 then return end
            consider(inst.Name, "")
            pcall(function()
                if inst:IsA("Tool") then consider(inst.Name, inst.TextureId) end
                for _, attr in ipairs({"Weapon","WeaponName","ItemName","Gun","CurrentWeapon","Equipped","Id","Item","Skin","Name"}) do
                    local a = inst:GetAttribute(attr)
                    if a then consider(tostring(a), tostring(inst:GetAttribute("Icon") or inst:GetAttribute("TextureId") or "")) end
                end
                -- Rivals item Info table sometimes mirrored as StringValues
                local info = inst:FindFirstChild("Info")
                if info then
                    local n = info:FindFirstChild("Name") or info:FindFirstChild("Id") or info:FindFirstChild("Type")
                    if n and n:IsA("ValueBase") then consider(tostring(n.Value), "") end
                    pcall(function()
                        if info:GetAttribute("Name") then consider(tostring(info:GetAttribute("Name")), "") end
                    end)
                end
            end)
            for _, c in ipairs(inst:GetChildren()) do scanInst(c, depth + 1) end
        end

        if plr.Character then
            scanInst(plr.Character, 0)
            for _, c in ipairs(plr.Character:GetDescendants()) do
                if c:IsA("Motor6D") or c:IsA("Weld") or c:IsA("WeldConstraint") then
                    for _, p in ipairs({c.Part0, c.Part1}) do
                        if p and p.Parent and p.Parent ~= plr.Character then
                            consider(p.Parent.Name, "")
                            consider(p.Name, "")
                        end
                    end
                end
            end
        end

        local bp = plr:FindFirstChild("Backpack")
        if bp then scanInst(bp, 0) end
        for _, n in ipairs({"Inventory","Weapons","Loadout","Gear","Items"}) do
            local f = plr:FindFirstChild(n)
            if f then scanInst(f, 0) end
        end

        -- 2) Rivals client objects: look for anything with EquippedItem / Items under player-related folders
        pcall(function()
            local rs = game:GetService("ReplicatedStorage")
            for _, folderName in ipairs({"ClientFighters","Fighters","Entities","Players","Replicas","Controllers"}) do
                local folder = rs:FindFirstChild(folderName, true)
                if folder then
                    for _, child in ipairs(folder:GetDescendants()) do
                        local ok, eq = pcall(function() return child:GetAttribute("EquippedItem") or child:FindFirstChild("EquippedItem") end)
                        if ok and eq then
                            if typeof(eq) == "Instance" then consider(eq.Name, "") end
                            if type(eq) == "string" then consider(eq, "") end
                        end
                    end
                end
            end
        end)

        -- 3) Player attributes
        pcall(function()
            for _, attr in ipairs({"Primary","Secondary","Melee","Utility","PrimaryWeapon","SecondaryWeapon","MeleeWeapon","CurrentWeapon","EquippedWeapon","Weapon","EquippedItem"}) do
                local a = plr:GetAttribute(attr)
                if a then
                    local resolved = resolveRivalsWeapon(tostring(a))
                    local kind = resolved and resolved.kind
                    if not kind then
                        local al = attr:lower()
                        kind = (al:find("melee") and "melee") or (al:find("second") and "secondary") or (al:find("util") and "util") or "primary"
                    end
                    set(kind, resolved and resolved.id or a, "")
                end
            end
        end)
        return out
    end

    local function setSlotImg(slot, weapon)
        if not slot then return end
        if slot.txt then slot.txt.Text = "" end -- solo imagen, sin nombres
        local assets = ensureRivalsWeaponIcons()
        local resolved = weapon and resolveRivalsWeapon(weapon.Name)
        local iconId = resolved and resolved.id or nil
        local asset = iconId and assets[iconId] or nil
        if asset then
            slot.img.Image = asset
            slot.img.ImageColor3 = Color3.fromRGB(255,255,255)
            slot.img.ImageTransparency = 0
            return
        end
        if weapon and weapon.TextureId and weapon.TextureId ~= "" then
            slot.img.Image = weapon.TextureId
            slot.img.ImageColor3 = Color3.fromRGB(255,255,255)
            slot.img.ImageTransparency = 0
            return
        end
        -- empty slot: blank (no placeholder clutter)
        slot.img.Image = ""
        slot.img.ImageTransparency = 1
    end

    local function setHighlight(target)
        local want = cfg({"Ragebot","TargetHUD","Highlight"}, false)
        if not want or not target or not target.Character then
            if highlightInst then pcall(function() highlightInst:Destroy() end) highlightInst = nil end
            return
        end
        if not highlightInst or highlightInst.Parent ~= target.Character then
            if highlightInst then pcall(function() highlightInst:Destroy() end) end
            highlightInst = Instance.new("Highlight")
            highlightInst.FillColor = Color3.fromRGB(100,200,255)
            highlightInst.OutlineColor = Color3.fromRGB(255,255,255)
            highlightInst.FillTransparency = 0.7
            highlightInst.OutlineTransparency = 0.15
            local htype = tostring(cfg({"Ragebot","TargetHUD","HighlightType"}, "AlwaysOnTop") or "AlwaysOnTop")
            highlightInst.DepthMode = (htype == "Occluded") and Enum.HighlightDepthMode.Occluded or Enum.HighlightDepthMode.AlwaysOnTop
            highlightInst.Parent = target.Character
        end
    end

    -- UE-style targeting: crosshair, closest, last target memory
    local function pickTarget()
        local cam = workspace.CurrentCamera
        local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")

        -- 1) ray center of screen (UE target ui)
        if cam then
            local ray = cam:ViewportPointToRay(cam.ViewportSize.X * 0.5, cam.ViewportSize.Y * 0.5)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = { LocalPlayer.Character }
            local hit = workspace:Raycast(ray.Origin, ray.Direction * 2500, params)
            if hit and hit.Instance then
                local model = hit.Instance:FindFirstAncestorOfClass("Model")
                local plr = model and Players:GetPlayerFromCharacter(model)
                if plr and plr ~= LocalPlayer then
                    lastTarget, lastTargetAt = plr, tick()
                    return plr
                end
            end
        end

        -- 2) closest living enemy to crosshair / distance
        local best, bestScore = nil, math.huge
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LocalPlayer and p.Character then
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                if hum and hum.Health > 0 and hrp then
                    local score = root and (hrp.Position - root.Position).Magnitude or 9999
                    if cam then
                        local sp, onScreen = cam:WorldToViewportPoint(hrp.Position)
                        if onScreen and sp.Z > 0 then
                            score = (Vector2.new(sp.X, sp.Y) - cam.ViewportSize * 0.5).Magnitude
                        else
                            score = score + 4000
                        end
                    end
                    if score < bestScore then bestScore, best = score, p end
                end
            end
        end
        if best then
            lastTarget, lastTargetAt = best, tick()
            return best
        end

        -- 3) remember last up to 10s (UE keeps card after elim)
        if lastTarget and (tick() - lastTargetAt) < 10 then
            return lastTarget
        end
        return nil
    end

    local function updateTargetHUD()
        if not hudRunning then return end
        local enabled = cfg({"Ragebot","TargetHUD","Enabled"}, false)
        if not enabled then
            if hudGui then hudGui.Enabled = false end
            if highlightInst then pcall(function() highlightInst:Destroy() end) highlightInst = nil end
            return
        end
        if not ensureTargetHUD() then return end
        hudGui.Enabled = true
        local px = tonumber(cfg({"Ragebot","TargetHUD","PosX"}, 50)) or 50
        local py = tonumber(cfg({"Ragebot","TargetHUD","PosY"}, 10)) or 10
        local scale = tonumber(cfg({"Ragebot","TargetHUD","Scale"}, 1)) or 1
        hudRoot.Size = UDim2.fromOffset(520 * scale, 132 * scale)
        -- only auto-place if user is not dragging; prefer free drag position
        if not hudRoot:GetAttribute("Dragging") then
            if freeHudPos then
                hudRoot.Position = UDim2.fromOffset(freeHudPos.X, freeHudPos.Y)
            else
                local cam = workspace.CurrentCamera
                local vp = cam and cam.ViewportSize or Vector2.new(1920, 1080)
                local x = (px / 100) * vp.X - (520 * scale) * 0.5
                local y = (py / 100) * vp.Y
                hudRoot.Position = UDim2.fromOffset(math.max(0, x), math.max(0, y))
            end
        end

        local target = pickTarget()
        if not target then
            hudName.Text = "No Target"
            hudMeta.Text = "level —  rank —  device —  streak —"
            hudHPNums.Text = "0 / 0"
            hudBar.Size = UDim2.fromScale(0,1)
            hudDmgVal.Text = "—   ▲ —   ▼ —"
            for _, sl in ipairs(slots) do setSlotImg(sl, nil) end
            setHighlight(nil)
            return
        end

        local char = target.Character
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        local hp = hum and hum.Health or 0
        local maxHp = (hum and hum.MaxHealth > 0) and hum.MaxHealth or 100
        local ratio = math.clamp(hp / math.max(maxHp,1), 0, 1)

        local level = getStat(target, {"Level","level","Lvl","PlayerLevel","AccountLevel"})
        local rank = getStat(target, {"Rank","rank","RankName","RankedRank","SeasonRank","Division","EloRank"})
        local streak = getStat(target, {"Streak","streak","Winstreak","WinStreak","KillStreak","CurrentStreak"})
        local device = getStat(target, {"Device","device","Platform","InputType","ClientDevice"})
        level = level ~= nil and tostring(level) or "?"
        rank = rank ~= nil and tostring(rank) or "?"
        streak = streak ~= nil and tostring(streak) or "0"
        device = device ~= nil and string.lower(tostring(device)) or "?"
        if device:find("mobile") or device == "1" then device = "mobile"
        elseif device:find("console") or device:find("gamepad") then device = "console"
        elseif device:find("pc") or device:find("desktop") or device == "0" then device = "pc" end

        hudName.Text = target.DisplayName or target.Name
        hudMeta.Text = string.format("level %s  rank %s  device %s  streak %s", level, rank, device, streak)
        hudHPNums.Text = string.format("%d / %d", math.floor(hp+0.5), math.floor(maxHp+0.5))
        hudBar.Size = UDim2.fromScale(ratio, 1)
        hudBar.BackgroundColor3 = ratio > 0.55 and Color3.fromRGB(100,165,230) or (ratio > 0.25 and Color3.fromRGB(230,180,70) or Color3.fromRGB(220,80,80))

        local dmg = tonumber(getStat(target, {"Damage","damage","DamageDealt","TotalDamage"})) or 0
        local kills = tonumber(getStat(target, {"Kills","kills","Eliminations"})) or 0
        local deaths = tonumber(getStat(target, {"Deaths","deaths"})) or 0
        if dmg == 0 then dmg = math.max(0, math.floor(maxHp - hp)) end
        hudDmgVal.Text = string.format("%d   ▲ %d   ▼ %d", math.floor(dmg), math.floor(kills), math.floor(deaths))

        local w = weaponsOf(target)
        -- remember weapons while alive so post-elim still shows loadout
        local hasAny = w.primary or w.secondary or w.melee or w.util
        if hasAny then
            lastWeapons = w
        elseif lastTarget == target and lastWeapons then
            w = lastWeapons
        end
        for _, sl in ipairs(slots) do setSlotImg(sl, w[sl.kind]) end
        setHighlight(target)
    end

    task.spawn(function()
        while hudRunning do
            pcall(updateTargetHUD)
            task.wait(0.03)
        end
        pcall(function()
            if hudGui then hudGui:Destroy() end
            hudGui = nil
        end)
    end)

    K.onUnload(function()
        stopSling()
        stopExpand()
        stopAA()
        stopTransloc()
        stopFakePos()
        stopVoidSpam()
        stopUERage()
        pcall(function()
            local g = (getgenv and getgenv()) or _G
            local store = g.Kyvweer_ReactiveStore
            if store and store.Data and store.Data.Ragebot and store.Data.Ragebot.TargetHUD then
                store.Data.Ragebot.TargetHUD.Enabled = false
            end
        end)
        destroyTargetHUD()
        -- wipe any leftover ScreenGui
        pcall(function()
            local pg = game:GetService("Players").LocalPlayer:FindFirstChild("PlayerGui")
            if pg then
                local old = pg:FindFirstChild("KyvweerTargetHUD")
                if old then old:Destroy() end
            end
        end)
    end)





end





--==========================================================================
--  Yabu beta ports: Ranked Charms + Spoof Weapon Ownership (full mask)
--==========================================================================
do
    local Players = game:GetService("Players")
    local RS = game:GetService("ReplicatedStorage")
    local LocalPlayer = Players.LocalPlayer

    local function genv()
        return (getgenv and getgenv()) or _G
    end

    local function safeRequire(inst)
        if not inst then return nil end
        local ok, mod = pcall(require, inst)
        if ok then return mod end
        return nil
    end

    ----------------------------------------------------------------
    -- Module resolution (same paths Yabu uses)
    ----------------------------------------------------------------
    local ilib, dctrl
    local function resolveModules()
        if not ilib then
            pcall(function()
                local modules = RS:FindFirstChild("Modules") or RS:WaitForChild("Modules", 5)
                if modules then
                    local itemLib = modules:FindFirstChild("ItemLibrary") or modules:WaitForChild("ItemLibrary", 5)
                    ilib = safeRequire(itemLib)
                end
            end)
        end
        if not dctrl then
            pcall(function()
                local ps = LocalPlayer:FindFirstChild("PlayerScripts") or LocalPlayer:WaitForChild("PlayerScripts", 5)
                if not ps then return end
                local controllers = ps:FindFirstChild("Controllers") or ps:WaitForChild("Controllers", 5)
                if not controllers then return end
                local pdc = controllers:FindFirstChild("PlayerDataController") or controllers:WaitForChild("PlayerDataController", 5)
                dctrl = safeRequire(pdc)
            end)
        end
        return ilib, dctrl
    end

    ----------------------------------------------------------------
    -- Ranked Charms visual hook (Yabu FormatSeasonRankCharm)
    ----------------------------------------------------------------
    local seasonLib, seasonOriginal, seasonReplacement
    local seasonNames = { [0] = "Zero", [1] = "Warp", [2] = "Polar", [3] = "Fame" }
    local seasonByName = { Zero = 0, Warp = 1, Polar = 2, Fame = 3 }

    local function seasonNumber(value)
        if type(value) == "number" then return value end
        if type(value) ~= "string" then return nil end
        return seasonByName[value] or tonumber((value):match("^Season (%d+)$")) or tonumber(value)
    end

    local function resolveSeasonLibrary()
        if seasonLib then return seasonLib end
        pcall(function()
            local modules = RS:FindFirstChild("Modules")
            local module = modules and modules:FindFirstChild("SeasonLibrary")
            if module then seasonLib = require(module) end
        end)
        return seasonLib
    end

    local function seasonMetadata(value)
        local g = genv()
        if not g.Kyvweer_RankedCharmsEnabled then return nil end
        local index = seasonNumber(value)
        if index == nil then return nil end
        local cfg = g.Kyvweer_RankedCharms and g.Kyvweer_RankedCharms[index]
        if not cfg or not cfg.enabled then return nil end
        local lib = resolveSeasonLibrary()
        local season = lib and lib.Seasons and lib.Seasons[cfg.seasonName or seasonNames[index]]
        local profile = season and season.RankProfile
        local rank = profile and profile.Ranks and profile.Ranks[cfg.rankName]
        if not rank then
            return {
                SeasonELO = 0,
                SeasonLeaderboardRank = math.clamp(math.floor(tonumber(cfg.rank) or 1), 1, 200),
            }
        end
        return {
            SeasonELO = rank.RequiredELO,
            SeasonLeaderboardRank = rank.RequiredELOLeaderboardRanking
                and math.clamp(math.floor(tonumber(cfg.rank) or 1), 1, 200)
                or nil,
        }
    end

    local function installSeasonHook()
        local lib = resolveSeasonLibrary()
        if not lib or type(lib.FormatSeasonRankCharm) ~= "function" then return false end
        if seasonOriginal then return true end
        seasonOriginal = lib.FormatSeasonRankCharm
        seasonReplacement = function(self, model, season, elo, arch)
            local md = seasonMetadata(season) or seasonMetadata(model and model.Name)
            if md then
                return seasonOriginal(self, model, season, md.SeasonELO, md.SeasonLeaderboardRank)
            end
            return seasonOriginal(self, model, season, elo, arch)
        end
        lib.FormatSeasonRankCharm = seasonReplacement
        return true
    end

    task.spawn(function()
        task.wait(1)
        installSeasonHook()
        while true do
            local g = genv()
            if g.Kyvweer_RankedCharmsEnabled then
                pcall(function()
                    installSeasonHook()
                    local roots = { workspace.CurrentCamera, LocalPlayer.Character }
                    local seen = setmetatable({}, { __mode = "k" })
                    local function restyle(model)
                        if typeof(model) ~= "Instance" or not model:IsA("Model") or seen[model] then return end
                        seen[model] = true
                        local index = seasonNumber(model.Name)
                        if index == nil then return end
                        local md = seasonMetadata(index)
                        if not md or not seasonLib or not seasonOriginal then return end
                        local season = seasonNames[index] or model.Name
                        pcall(seasonLib.FormatSeasonRankCharm, seasonLib, model, season, md.SeasonELO, md.SeasonLeaderboardRank)
                    end
                    for _, root in ipairs(roots) do
                        if typeof(root) == "Instance" then
                            restyle(root)
                            for _, d in ipairs(root:GetDescendants()) do restyle(d) end
                        end
                    end
                end)
            end
            task.wait(1.5)
        end
    end)

    ----------------------------------------------------------------
    -- Spoof Weapon Ownership — exact Yabu unlock mask pattern
    -- Replaces CurrentData.Data with a proxy; WeaponInventory reads
    -- go through build_owned_weapons (array form with all ItemLibrary weapons).
    ----------------------------------------------------------------
    local unlockMaskTarget, unlockMaskInner = nil, nil
    local unlockMaskConnection = nil
    local unlockedWeaponCache = nil
    local unlock_rev = 0
    local unlock_memo = {}
    local unlockSpoof = {} -- key -> transform(real) function

    local function memoize_unlock(key, build)
        return function(real)
            local count = 0
            if type(real) == "table" then
                for _ in next, real do count = count + 1 end
            end
            local m = unlock_memo[key]
            if m and m.real == real and m.rev == unlock_rev and m.count == count then
                return m.value
            end
            local value = build(real)
            unlock_memo[key] = { real = real, rev = unlock_rev, count = count, value = value }
            return value
        end
    end

    -- Yabu build_owned_weapons: array of {Name, Level, XP, Prestige}
    local function build_owned_weapons(real)
        local out, present = {}, {}
        if type(real) == "table" then
            for index, entry in ipairs(real) do
                out[index] = entry
                if type(entry) == "table" and type(entry.Name) == "string" then
                    present[entry.Name] = true
                end
            end
            -- also handle map form just in case
            if #out == 0 then
                for k, entry in pairs(real) do
                    if type(entry) == "table" and type(entry.Name) == "string" then
                        table.insert(out, entry)
                        present[entry.Name] = true
                    elseif type(k) == "string" and type(entry) == "table" then
                        local e = table.clone(entry)
                        e.Name = e.Name or k
                        table.insert(out, e)
                        present[k] = true
                    end
                end
            end
        end
        if not unlockedWeaponCache then
            unlockedWeaponCache = {}
            local items = (ilib and ilib.Items) or {}
            for name, item in pairs(items) do
                if type(name) == "string" and type(item) == "table" then
                    table.insert(unlockedWeaponCache, name)
                end
            end
            table.sort(unlockedWeaponCache)
        end
        for _, name in ipairs(unlockedWeaponCache) do
            if not present[name] then
                table.insert(out, { Name = name, Level = 1, XP = 0, Prestige = 0 })
            end
        end
        return out
    end

    local everyOwnedWeapon = memoize_unlock("weapons", build_owned_weapons)

    local function removeUnlockMask()
        if unlockMaskTarget == nil then return end
        local target, inner = unlockMaskTarget, unlockMaskInner
        unlockMaskTarget, unlockMaskInner = nil, nil
        pcall(function()
            if target and inner then
                rawset(target, "Data", inner)
            end
        end)
    end

    local function installUnlockMask()
        resolveModules()
        if not dctrl then return false, "PlayerDataController missing" end
        local current = dctrl.CurrentData
        if current == nil then return false, "player data is still loading" end
        if current == unlockMaskTarget then return true end
        removeUnlockMask()
        local inner = rawget(current, "Data")
        if type(inner) ~= "table" then return false, "CurrentData.Data is not ready" end
        local proxy = setmetatable({}, {
            __index = function(_, key)
                local transform = unlockSpoof[key]
                if transform ~= nil then
                    return transform(inner[key])
                end
                return inner[key]
            end,
            __newindex = function(_, key, value)
                inner[key] = value
            end,
            __iter = function()
                return next, inner
            end,
            __len = function()
                return #inner
            end,
        })
        rawset(current, "Data", proxy)
        unlockMaskTarget, unlockMaskInner = current, inner
        return true
    end

    local function refreshUnlockField(key)
        pcall(function()
            resolveModules()
            if not dctrl then return end
            local current = dctrl.CurrentData
            if current and type(current.GetDataChangedSignal) == "function" then
                local sig = current:GetDataChangedSignal(key)
                if sig then
                    local value = current:Get(key)
                    sig:Fire(value, key)
                end
            elseif current and type(current.Replicate) == "function" then
                current:Replicate(key)
            end
        end)
        -- also try Kyvweer-style _value_changed_events
        pcall(function()
            if not dctrl or not dctrl.CurrentData then return end
            local current = dctrl.CurrentData
            local events = rawget(current, "_value_changed_events")
            if type(events) == "table" and events[key] then
                local ev = events[key]
                if type(ev) == "table" and type(ev.Fire) == "function" then
                    ev:Fire(current:Get(key), key)
                elseif typeof(ev) == "Instance" or type(ev) == "userdata" then
                    pcall(function() ev:Fire(current:Get(key), key) end)
                end
            end
        end)
    end

    local function ensureUnlockMaskWatcher()
        if unlockMaskConnection ~= nil then return end
        pcall(function()
            resolveModules()
            if not dctrl or not dctrl.PlayerDataAdded then return end
            unlockMaskConnection = dctrl.PlayerDataAdded:Connect(function()
                if not genv().Kyvweer_SpoofWeaponOwnership then return end
                task.defer(function()
                    -- reinstall after data reload
                    unlockMaskTarget, unlockMaskInner = nil, nil
                    syncWeaponOwnershipMask()
                end)
            end)
        end)
    end

    function syncWeaponOwnershipMask()
        resolveModules()
        unlock_rev = unlock_rev + 1
        unlockedWeaponCache = nil -- rebuild from ilib
        local enabled = genv().Kyvweer_SpoofWeaponOwnership == true
        if enabled then
            unlockSpoof.WeaponInventory = everyOwnedWeapon
            local ok, why = installUnlockMask()
            if not ok then
                warn("[Kyvweer] Weapon ownership mask: " .. tostring(why))
                return false, why
            end
            ensureUnlockMaskWatcher()
            refreshUnlockField("WeaponInventory")
            refreshUnlockField("WeaponData")
            return true
        else
            unlockSpoof.WeaponInventory = nil
            if next(unlockSpoof) == nil then
                removeUnlockMask()
            else
                -- mask still needed for other keys; just refresh
                installUnlockMask()
            end
            refreshUnlockField("WeaponInventory")
            refreshUnlockField("WeaponData")
            return true
        end
    end

    -- Public API used by Overview toggle
    genv().Kyvweer_SyncWeaponOwnership = syncWeaponOwnershipMask

    -- Watch flag changes (toggle may set flag before modules ready)
    task.spawn(function()
        local last = false
        while true do
            resolveModules()
            local on = genv().Kyvweer_SpoofWeaponOwnership == true
            if on ~= last then
                last = on
                pcall(syncWeaponOwnershipMask)
            elseif on and unlockMaskTarget == nil then
                -- data may have loaded late
                pcall(syncWeaponOwnershipMask)
            elseif on and dctrl and dctrl.CurrentData and dctrl.CurrentData ~= unlockMaskTarget then
                unlockMaskTarget, unlockMaskInner = nil, nil
                pcall(syncWeaponOwnershipMask)
            end
            task.wait(0.5)
        end
    end)

    -- Hook CurrentData:Get as secondary path (some code paths bypass .Data index)
    task.spawn(function()
        task.wait(1)
        resolveModules()
        if not dctrl then return end
        pcall(function()
            local current = dctrl.CurrentData
            if not current or type(current.Get) ~= "function" then return end
            -- wrap via metatable if possible, else leave mask as primary
            local mt = getmetatable(current)
            -- don't break ReplicatedClass; mask on Data is the Yabu primary path
        end)
        -- Also wrap dctrl.Get if it exists at controller level
        pcall(function()
            if type(dctrl.Get) == "function" and not dctrl.__kyvweer_weapon_hooked then
                local old = dctrl.Get
                dctrl.Get = function(self, key, ...)
                    if key == "WeaponInventory" and genv().Kyvweer_SpoofWeaponOwnership then
                        local real = old(self, key, ...)
                        return everyOwnedWeapon(real)
                    end
                    return old(self, key, ...)
                end
                dctrl.__kyvweer_weapon_hooked = true
            end
        end)
    end)

    K.onUnload(function()
        pcall(function()
            genv().Kyvweer_SpoofWeaponOwnership = false
            unlockSpoof.WeaponInventory = nil
            removeUnlockMask()
        end)
        pcall(function()
            if seasonLib and seasonOriginal and seasonLib.FormatSeasonRankCharm == seasonReplacement then
                seasonLib.FormatSeasonRankCharm = seasonOriginal
            end
        end)
        genv().Kyvweer_RankedCharmsEnabled = false
        if unlockMaskConnection then
            pcall(function() unlockMaskConnection:Disconnect() end)
            unlockMaskConnection = nil
        end
    end)
end






--==========================================================================
--  Counter UE + Newminy Counter (estilo clips HVH)
--==========================================================================
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer

    local function storeRB(section)
        local g = (getgenv and getgenv()) or _G
        local store = g.Kyvweer_ReactiveStore
        if store and store.Data and store.Data.Ragebot then
            return store.Data.Ragebot[section]
        end
        return nil
    end

    local function sectionOn(section)
        local d = storeRB(section)
        if type(d) ~= "table" then return false end
        local kb = d.Keybind
        if type(kb) == "table" then
            local kind = kb.Kind or "Toggle"
            if kind == "Always" then return d.Enabled == true end
            if kb.State == true then return true end
            if kb.State == false then return false end
        end
        return d.Enabled == true
    end

    local function getCfg(section, key, default)
        local d = storeRB(section)
        if type(d) == "table" and d[key] ~= nil then return d[key] end
        return default
    end

    local function getRoot()
        local c = LocalPlayer.Character
        return c and c:FindFirstChild("HumanoidRootPart")
    end

    local function getHead(char)
        return char and (char:FindFirstChild("Head") or char:FindFirstChild("head"))
    end

    local function isEnemy(p)
        if not p or p == LocalPlayer then return false end
        if not p.Character then return false end
        local hum = p.Character:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then return false end
        local ok = true
        pcall(function()
            if p.Team and LocalPlayer.Team and p.Team == LocalPlayer.Team then
                ok = false
            end
        end)
        return ok
    end

    local tracks = {}

    local function dumpShots(aimPos, head, hrp, char, attempts)
        local tool
        pcall(function()
            local c = LocalPlayer.Character
            if not c then return end
            tool = c:FindFirstChildOfClass("Tool")
            if not tool then
                local bp = LocalPlayer:FindFirstChild("Backpack")
                if bp then
                    for _, x in ipairs(bp:GetChildren()) do
                        if x:IsA("Tool") then tool = x; x.Parent = c; break end
                    end
                end
            end
        end)
        local n = math.clamp(math.floor(tonumber(attempts) or 80), 20, 200)
        for _ = 1, n do
            if tool then pcall(function() tool:Activate() end) end
            pcall(function()
                if not tool then return end
                for _, d in ipairs(tool:GetDescendants()) do
                    if d:IsA("RemoteEvent") then
                        pcall(function() d:FireServer(aimPos) end)
                        pcall(function() d:FireServer(head or hrp, aimPos) end)
                        pcall(function() d:FireServer(char, aimPos) end)
                    end
                end
            end)
            pcall(function()
                local vim = game:GetService("VirtualInputManager")
                vim:SendMouseButtonEvent(0, 0, 0, true, game, 0)
                vim:SendMouseButtonEvent(0, 0, 0, false, game, 0)
            end)
        end
    end

    local function killTarget(p, data, section)
        local char = p.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        local head = getHead(char)
        local root = getRoot()
        if not hrp or not root then return end
        local aimPos = (data and data.lastStable) or hrp.Position
        if (hrp.Position - aimPos).Magnitude < 80 then aimPos = hrp.Position end
        if head then aimPos = head.Position end
        local height = tonumber(getCfg(section, "StickHeight", 1)) or 1
        pcall(function()
            root.CFrame = CFrame.new(aimPos + Vector3.new(0, height + 0.5, 0), aimPos)
            root.AssemblyLinearVelocity = Vector3.zero
        end)
        pcall(function()
            local cam = workspace.CurrentCamera
            if cam then cam.CFrame = CFrame.new(cam.CFrame.Position, aimPos) end
        end)
        dumpShots(aimPos, head, hrp, char, getCfg(section, "ShootAttempts", 80))
    end

    local function updateTracks()
        local now = tick()
        for _, p in ipairs(Players:GetPlayers()) do
            if isEnemy(p) then
                local hrp = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local t = tracks[p]
                    if not t then
                        tracks[p] = { lastPos = hrp.Position, lastStable = hrp.Position, lastT = now, flags = 0 }
                    else
                        local dist = (hrp.Position - t.lastPos).Magnitude
                        local dt = math.max(now - t.lastT, 1e-3)
                        local speed = dist / dt
                        -- UE / void / desync detection
                        if dist > 4 or speed > 45 or hrp.Position.Y > 80 or hrp.Position.Y < -2 then
                            t.flags = (t.flags or 0) + 1
                        else
                            t.lastStable = hrp.Position
                            t.flags = math.max((t.flags or 0) - 1, 0)
                        end
                        -- underground / sleepy style
                        if hrp.Position.Y < (t.lastStable.Y - 2) and dist < 60 then
                            t.underFlags = (t.underFlags or 0) + 1
                        else
                            t.underFlags = math.max((t.underFlags or 0) - 1, 0)
                        end
                        t.lastPos = hrp.Position
                        t.lastT = now
                    end
                end
            end
        end
    end

    local function protectSelf(section)
        if getCfg(section, "AntiDamage", true) ~= true and getCfg(section, "GodHeal", true) ~= true then return end
        local char = LocalPlayer.Character
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if hum then
            pcall(function()
                hum.Health = hum.MaxHealth
                hum.MaxHealth = math.max(hum.MaxHealth, 100)
            end)
        end
        pcall(function()
            if not char:FindFirstChildOfClass("ForceField") then
                local ff = Instance.new("ForceField")
                ff.Visible = false
                ff.Parent = char
            end
        end)
        -- no CanCollide/CanTouch strip: avoids invisible walls / slide bugs

    end

    -- UE Counter loop
    local cuConn
    local function tickUE()
        if not sectionOn("CounterUE") then return end
        updateTracks()
        protectSelf("CounterUE")
        local thr = tonumber(getCfg("CounterUE", "DetectThreshold", 12)) or 12
        local maxD = tonumber(getCfg("CounterUE", "MaxDistance", 5000)) or 5000
        local root = getRoot()
        if not root then return end
        local list = {}
        for p, data in pairs(tracks) do
            if isEnemy(p) and (data.flags or 0) >= 1 then
                local hrp = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
                if hrp and (hrp.Position - root.Position).Magnitude <= maxD then
                    table.insert(list, { p = p, data = data, score = data.flags })
                end
            end
        end
        table.sort(list, function(a, b) return a.score > b.score end)
        for i = 1, math.min(#list, 4) do
            if getCfg("CounterUE", "AutoShoot", true) then
                killTarget(list[i].p, list[i].data, "CounterUE")
            end
        end
    end

    -- Newminy Counter (underground / sleepy desync)
    local function tickNewminy()
        if not sectionOn("CounterSleepy") then return end
        updateTracks()
        protectSelf("CounterSleepy")
        local maxD = tonumber(getCfg("CounterSleepy", "MaxDistance", 5000)) or 5000
        local root = getRoot()
        if not root then return end
        local list = {}
        for p, data in pairs(tracks) do
            if isEnemy(p) and (data.underFlags or 0) >= 1 then
                local hrp = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
                if hrp and (hrp.Position - root.Position).Magnitude <= maxD then
                    table.insert(list, { p = p, data = data, score = data.underFlags })
                end
            end
        end
        table.sort(list, function(a, b) return a.score > b.score end)
        for i = 1, math.min(#list, 4) do
            if getCfg("CounterSleepy", "AutoShoot", true) then
                killTarget(list[i].p, list[i].data, "CounterSleepy")
            end
        end
    end

    local function tickGeneric(section, flagKey)
        if not sectionOn(section) then return end
        updateTracks()
        protectSelf(section)
        local maxD = tonumber(getCfg(section, "MaxDistance", 5000)) or 5000
        local root = getRoot()
        if not root then return end
        local list = {}
        for p, data in pairs(tracks) do
            local flags = (data.flags or 0) + (data.underFlags or 0)
            if isEnemy(p) and flags >= 1 then
                local hrp = p.Character and p.Character:FindFirstChild("HumanoidRootPart")
                if hrp and (hrp.Position - root.Position).Magnitude <= maxD then
                    table.insert(list, { p = p, data = data, score = flags })
                end
            end
        end
        table.sort(list, function(a, b) return a.score > b.score end)
        for i = 1, math.min(#list, 4) do
            if getCfg(section, "AutoShoot", true) then
                killTarget(list[i].p, list[i].data, section)
            end
        end
    end

    local counterAcc = 0
    RunService.Heartbeat:Connect(function(dt)
        counterAcc = counterAcc + (dt or 0.016)
        if counterAcc < 0.06 then return end
        counterAcc = 0
        pcall(tickUE)
        pcall(tickNewminy)
        pcall(function() tickGeneric("CounterNewminy") end)
        pcall(function() tickGeneric("CounterKicia") end)
        pcall(function() tickGeneric("CounterTranslocate") end)
    end)
end




--==========================================================================
--  UE-style Flight (camera-relative, lobby + in-round)
--==========================================================================
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local UIS = game:GetService("UserInputService")
    local lp = Players.LocalPlayer

    local att, lv
    local wasOn = false

    local function clearMover()
        if lv then pcall(function() lv:Destroy() end) lv = nil end
        if att then pcall(function() att:Destroy() end) att = nil end
    end

    local function flightCfg()
        local g = (getgenv and getgenv()) or _G
        local store = g.Kyvweer_ReactiveStore
        if not store or not store.Data or not store.Data.Movement then
            return false, 100
        end
        local flight = store.Data.Movement.Flight
        if type(flight) ~= "table" then return false, 100 end
        local kb = flight.Keybind
        local on = false
        if type(kb) == "table" then
            local kind = kb.Kind or "Always"
            if kind == "Hold" or kind == "Toggle" then
                on = kb.State == true
            else
                on = flight.Enabled == true
            end
        else
            on = flight.Enabled == true
        end
        return on, math.clamp(tonumber(flight.Speed) or 100, 1, 1000)
    end

    local function inputDir(cam)
        local f = (UIS:IsKeyDown(Enum.KeyCode.W) and 1 or 0) - (UIS:IsKeyDown(Enum.KeyCode.S) and 1 or 0)
        local r = (UIS:IsKeyDown(Enum.KeyCode.D) and 1 or 0) - (UIS:IsKeyDown(Enum.KeyCode.A) and 1 or 0)
        local u = (UIS:IsKeyDown(Enum.KeyCode.Space) and 1 or 0) - ((UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.LeftShift) or UIS:IsKeyDown(Enum.KeyCode.C)) and 1 or 0)
        if f == 0 and r == 0 and u == 0 then return Vector3.zero end
        local cf = cam and cam.CFrame or CFrame.new()
        -- UE-style: horizontal from camera look flattened, vertical absolute
        local look = Vector3.new(cf.LookVector.X, 0, cf.LookVector.Z)
        if look.Magnitude > 0 then look = look.Unit else look = Vector3.new(0, 0, -1) end
        local right = Vector3.new(cf.RightVector.X, 0, cf.RightVector.Z)
        if right.Magnitude > 0 then right = right.Unit else right = Vector3.new(1, 0, 0) end
        local dir = look * f + right * r + Vector3.new(0, 1, 0) * u
        if dir.Magnitude > 0 then return dir.Unit end
        return Vector3.zero
    end

    local function ensureMover(root)
        if att and att.Parent == root and lv and lv.Parent == root then return end
        clearMover()
        att = Instance.new("Attachment")
        att.Name = "KyvweerUEFlyAtt"
        att.Parent = root
        lv = Instance.new("LinearVelocity")
        lv.Name = "KyvweerUEFlyLV"
        lv.Attachment0 = att
        lv.RelativeTo = Enum.ActuatorRelativeTo.World
        lv.ForceLimitMode = Enum.ForceLimitMode.PerAxis
        pcall(function()
            lv.MaxAxesForce = Vector3.new(math.huge, math.huge, math.huge)
        end)
        pcall(function()
            lv.MaxForce = math.huge
        end)
        lv.Parent = root
    end

    RunService.Heartbeat:Connect(function()
        local on, speed = flightCfg()
        local char = lp.Character
        local root = char and (char:FindFirstChild("HumanoidRootPart") or char:FindFirstChild("UpperTorso"))
        local hum = char and char:FindFirstChildOfClass("Humanoid")

        if not on or not root then
            if wasOn then
                clearMover()
                if hum then pcall(function() hum.PlatformStand = false end) end
            end
            wasOn = false
            return
        end
        wasOn = true

        pcall(function()
            if root.Anchored then root.Anchored = false end
            if hum then
                hum.PlatformStand = true
                hum.AutoRotate = false
            end
        end)

        ensureMover(root)
        local cam = workspace.CurrentCamera
        local dir = inputDir(cam)
        if dir.Magnitude > 0 then
            lv.VectorVelocity = dir * speed
        else
            -- hover: kill gravity drift
            lv.VectorVelocity = Vector3.zero
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
        -- face move direction lightly
        if dir.Magnitude > 0.1 then
            local flat = Vector3.new(dir.X, 0, dir.Z)
            if flat.Magnitude > 0.05 then
                pcall(function()
                    root.CFrame = CFrame.new(root.Position, root.Position + flat)
                end)
            end
        end
    end)

    lp.CharacterAdded:Connect(function()
        clearMover()
        wasOn = false
    end)
end

-- Light collision restore on spawn only (no heartbeat — avoids weird movement / failed loads)
do
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer
    local function softRestore(char)
        if not char then return end
        task.defer(function()
            task.wait(0.5)
            for _, name in ipairs({"HumanoidRootPart", "Head", "UpperTorso", "LowerTorso", "Torso"}) do
                local p = char:FindFirstChild(name)
                if p and p:IsA("BasePart") then
                    pcall(function()
                        p.Anchored = false
                    end)
                end
            end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum then
                pcall(function()
                    hum.PlatformStand = false
                end)
            end
        end)
    end
    if lp.Character then softRestore(lp.Character) end
    lp.CharacterAdded:Connect(softRestore)
end

--  Arcade Mode (UE) — Ragebot apartado (like Fake Position)
--==========================================================================
do
    local Players = game:GetService("Players")
    local LocalPlayer = Players.LocalPlayer

    local function arcadeGet(key, default)
        local g = (getgenv and getgenv()) or _G
        local store = g.Kyvweer_ReactiveStore
        if store and store.Data and store.Data.Ragebot and store.Data.Ragebot.Arcade then
            local v = store.Data.Ragebot.Arcade[key]
            if v ~= nil then return v end
        end
        if K and K.Config and K.Config.store then
            local ok, v = pcall(function()
                return K.Config.store:Get({"Ragebot", "Arcade", key}, true)
            end)
            if ok and v ~= nil then return v end
        end
        return default
    end

    -- Auto Respawn
    local respawnBusy = false
    local function tryRespawn()
        if respawnBusy then return end
        if not arcadeGet("AutoRespawn", false) then return end
        respawnBusy = true
        local delay = tonumber(arcadeGet("RespawnDelay", 0.5)) or 0.5
        task.delay(math.max(0, delay), function()
            respawnBusy = false
            if not arcadeGet("AutoRespawn", false) then return end
            local char = LocalPlayer.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if hum and hum.Health > 0 then return end
            pcall(function() LocalPlayer:LoadCharacter() end)
            pcall(function()
                local rs = game:GetService("ReplicatedStorage")
                for _, name in ipairs({"Respawn", "RequestRespawn", "RespawnCharacter", "LoadCharacter"}) do
                    local r = rs:FindFirstChild(name, true)
                    if r and r:IsA("RemoteEvent") then pcall(function() r:FireServer() end)
                    elseif r and r:IsA("RemoteFunction") then pcall(function() r:InvokeServer() end) end
                end
            end)
            pcall(function()
                local pg = LocalPlayer:FindFirstChild("PlayerGui")
                if not pg then return end
                for _, gui in ipairs(pg:GetDescendants()) do
                    if gui:IsA("TextButton") or gui:IsA("ImageButton") then
                        local t = ((gui.Text or "") .. " " .. gui.Name):lower()
                        if t:find("respawn") or t:find("play again") or t:find("redeploy") then
                            pcall(function() firesignal(gui.MouseButton1Click) end)
                        end
                    end
                end
            end)
        end)
    end

    local function hookHumanoid(hum)
        if not hum then return end
        hum.Died:Connect(tryRespawn)
        hum.HealthChanged:Connect(function(h)
            if h <= 0 then tryRespawn() end
        end)
    end
    if LocalPlayer.Character then
        hookHumanoid(LocalPlayer.Character:FindFirstChildOfClass("Humanoid"))
    end
    LocalPlayer.CharacterAdded:Connect(function(char)
        respawnBusy = false
        hookHumanoid(char:WaitForChild("Humanoid", 5))
    end)
    task.spawn(function()
        while true do
            task.wait(0.4)
            if arcadeGet("AutoRespawn", false) then
                local char = LocalPlayer.Character
                local hum = char and char:FindFirstChildOfClass("Humanoid")
                if not char or not hum or hum.Health <= 0 then tryRespawn() end
            end
        end
    end)

    -- Auto Ammo
    local function refillAmmo()
        if not arcadeGet("AutoAmmo", false) then return end
        local char = LocalPlayer.Character
        if not char then return end
        local function patchTool(tool)
            if not tool or not tool:IsA("Tool") then return end
            for _, v in ipairs(tool:GetDescendants()) do
                if v:IsA("NumberValue") or v:IsA("IntValue") then
                    local n = v.Name:lower()
                    if n:find("ammo") or n:find("clip") or n:find("magazine") or n:find("rounds") then
                        local maxV = nil
                        for _, m in ipairs(tool:GetDescendants()) do
                            if (m:IsA("NumberValue") or m:IsA("IntValue")) then
                                local mn = m.Name:lower()
                                if mn:find("max") and (mn:find("ammo") or mn:find("clip") or mn:find("mag")) then
                                    maxV = m.Value
                                    break
                                end
                            end
                        end
                        pcall(function() v.Value = maxV or math.max(v.Value, 30) end)
                    end
                end
            end
            pcall(function()
                for _, attr in ipairs({"Ammo", "ammo", "Clip", "Magazine", "CurrentAmmo"}) do
                    local val = tool:GetAttribute(attr)
                    if type(val) == "number" then
                        tool:SetAttribute(attr, tool:GetAttribute("MaxAmmo") or tool:GetAttribute("MaxClip") or 30)
                    end
                end
            end)
        end
        for _, t in ipairs(char:GetChildren()) do
            if t:IsA("Tool") then patchTool(t) end
        end
        local bp = LocalPlayer:FindFirstChild("Backpack")
        if bp then
            for _, t in ipairs(bp:GetChildren()) do
                if t:IsA("Tool") then patchTool(t) end
            end
        end
        pcall(function()
            local rs = game:GetService("ReplicatedStorage")
            for _, name in ipairs({"Reload", "RequestReload", "RefillAmmo", "GiveAmmo"}) do
                local r = rs:FindFirstChild(name, true)
                if r and r:IsA("RemoteEvent") then pcall(function() r:FireServer() end) end
            end
        end)
    end

    task.spawn(function()
        while true do
            local interval = tonumber(arcadeGet("AmmoInterval", 0.25)) or 0.25
            task.wait(math.max(0.05, interval))
            pcall(refillAmmo)
        end
    end)
end





--==========================================================================
--==========================================================================
--  FULL Identity Spoof (Name + Avatar everywhere client can show them)
--==========================================================================
do
    local Players = game:GetService("Players")
    local RunService = game:GetService("RunService")
    local LocalPlayer = Players.LocalPlayer

    local function G()
        return (getgenv and getgenv()) or _G
    end

    local function store()
        local st
        pcall(function()
            if tbl17 and type(tbl17.bG) == "function" then
                st = tbl17.bG()
            end
        end)
        if type(st) == "table" and type(st.Data) == "table" then
            G().Kyvweer_ReactiveStore = st
            return st
        end
        return G().Kyvweer_ReactiveStore
    end

    local function field(scope, name)
        local st = store()
        local ps = st and st.Data and st.Data.PlayerSpoofer
        local sc = ps and ps[scope]
        local f = sc and sc[name]
        if type(f) ~= "table" then return false, nil end
        return f.Enabled == true, f.Value
    end

    local function uidFrom(v)
        if type(v) == "number" and v > 0 then return math.floor(v) end
        if type(v) == "string" then
            local n = tonumber((v:match("%d+") or ""))
            if n and n > 0 then return n end
        end
        return nil
    end

    local function spoofUid()
        local on, v = field("LocalPlayer", "Avatar")
        if not on then return nil end
        return uidFrom(v)
    end

    local function spoofName()
        local on, v = field("LocalPlayer", "Name")
        if on and v ~= nil and tostring(v) ~= "" then return tostring(v) end
        return nil
    end

    local function spoofDisplay()
        local on, v = field("LocalPlayer", "DisplayName")
        if on and v ~= nil and tostring(v) ~= "" then return tostring(v) end
        return nil
    end

    ----------------------------------------------------------------
    -- Avatar description cache
    ----------------------------------------------------------------
    local descCache = {}
    local function description(uid)
        if descCache[uid] then return descCache[uid] end
        local ok, desc = pcall(function()
            return Players:GetHumanoidDescriptionFromUserIdAsync(uid)
        end)
        if ok and desc then
            descCache[uid] = desc
            return desc
        end
        return nil
    end

    local lastApplied = 0
    local function applyBodyAvatar(force)
        local uid = spoofUid()
        if not uid then return end
        if not force and (tick() - lastApplied) < 0.8 then return end
        local char = LocalPlayer.Character
        if not char then return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum then return end
        local desc = description(uid)
        if not desc then return end
        local ok = pcall(function()
            hum:ApplyDescriptionReset(desc)
        end)
        if not ok then
            pcall(function() hum:ApplyDescription(desc) end)
        end
        -- keep description on humanoid for some UIs
        pcall(function()
            local hd = hum:FindFirstChildOfClass("HumanoidDescription")
            if not hd then
                desc:Clone().Parent = hum
            end
        end)
        lastApplied = tick()
    end

    ----------------------------------------------------------------
    -- API hooks (Roblox + Rivals call these for faces / profiles)
    ----------------------------------------------------------------
    local hooked = false
    local function installHooks()
        if hooked then return end
        hooked = true

        pcall(function()
            local old = Players.GetUserThumbnailAsync
            if type(old) ~= "function" then return end
            Players.GetUserThumbnailAsync = function(self, userId, thumbType, thumbSize, ...)
                local uid = spoofUid()
                if uid and tonumber(userId) == LocalPlayer.UserId then
                    userId = uid
                end
                return old(self, userId, thumbType, thumbSize, ...)
            end
        end)

        pcall(function()
            local old = Players.GetHumanoidDescriptionFromUserIdAsync
            if type(old) ~= "function" then return end
            Players.GetHumanoidDescriptionFromUserIdAsync = function(self, userId, ...)
                local uid = spoofUid()
                if uid and tonumber(userId) == LocalPlayer.UserId then
                    local d = description(uid)
                    if d then
                        local ok, c = pcall(function() return d:Clone() end)
                        if ok and c then return c end
                    end
                    userId = uid
                end
                return old(self, userId, ...)
            end
        end)

        -- some games use GetHumanoidDescriptionFromUserId (non async name)
        pcall(function()
            local old = Players.GetHumanoidDescriptionFromUserId
            if type(old) ~= "function" then return end
            Players.GetHumanoidDescriptionFromUserId = function(self, userId, ...)
                local uid = spoofUid()
                if uid and tonumber(userId) == LocalPlayer.UserId then
                    userId = uid
                end
                return old(self, userId, ...)
            end
        end)
    end

    ----------------------------------------------------------------
    -- Thumbnail content cache for image rewrites
    ----------------------------------------------------------------
    local shotCache = {}
    local function thumb(uid, kind)
        kind = kind or "head"
        local key = tostring(uid) .. kind
        if shotCache[key] then return shotCache[key] end
        local ttype = Enum.ThumbnailType.HeadShot
        if kind == "bust" then ttype = Enum.ThumbnailType.AvatarBust end
        if kind == "full" then ttype = Enum.ThumbnailType.AvatarThumbnail end
        local ok, content = pcall(function()
            return Players:GetUserThumbnailAsync(uid, ttype, Enum.ThumbnailSize.Size420x420)
        end)
        if ok and content and content ~= "" then
            shotCache[key] = content
            return content
        end
        return nil
    end

    local function rewriteImage(img, myId, uid)
        if not (img:IsA("ImageLabel") or img:IsA("ImageButton")) then return end
        local cur = tostring(img.Image or "")
        if cur == "" then return end
        local low = cur:lower()
        local isMine = cur:find(myId, 1, true) ~= nil
        local isAvatarAsset = low:find("avatar") ~= nil or low:find("headshot") ~= nil
            or low:find("thumbnail") ~= nil or low:find("bust") ~= nil
            or low:find("rbxthumb") ~= nil or low:find("roblox.com") ~= nil
        -- rewrite if URL is local player OR classic avatar thumb patterns parented under player-ish UI
        if isMine then
            local kind = "head"
            if low:find("bust") then kind = "bust"
            elseif low:find("thumbnail") and not low:find("head") then kind = "full" end
            local content = thumb(uid, kind)
            if content then
                pcall(function() img.Image = content end)
            else
                pcall(function() img.Image = cur:gsub(myId, tostring(uid)) end)
            end
            return
        end
        -- name-based face slots (Rivals profile cards)
        local n = (img.Name or ""):lower()
        local p = img.Parent and (img.Parent.Name or ""):lower() or ""
        if (n:find("avatar") or n:find("head") or n:find("icon") or n:find("thumb") or n:find("portrait") or n:find("face")
            or p:find("avatar") or p:find("profile") or p:find("player") or p:find("card")) and isAvatarAsset then
            -- only if nearby text contains local name/display (likely our card)
            local mine = false
            local rn, rd = LocalPlayer.Name, LocalPlayer.DisplayName
            local sn, sd = spoofName(), spoofDisplay()
            local root = img.Parent
            for _ = 1, 4 do
                if not root then break end
                for _, sib in ipairs(root:GetChildren()) do
                    if sib:IsA("TextLabel") or sib:IsA("TextButton") then
                        local t = sib.Text or ""
                        if t == rn or t == rd or (sn and t == sn) or (sd and t == sd) then
                            mine = true
                            break
                        end
                    end
                end
                if mine then break end
                root = root.Parent
            end
            if mine then
                local content = thumb(uid, "head")
                if content then pcall(function() img.Image = content end) end
            end
        end
    end

    local function applyAllFaces()
        local uid = spoofUid()
        if not uid then return end
        local myId = tostring(LocalPlayer.UserId)
        local function scan(root)
            if not root then return end
            for _, d in ipairs(root:GetDescendants()) do
                pcall(rewriteImage, d, myId, uid)
            end
        end
        pcall(function() scan(LocalPlayer:FindFirstChild("PlayerGui")) end)
        pcall(function()
            local cg = game:GetService("CoreGui")
            -- Player list / inspect only (not entire CoreGui random assets)
            for _, name in ipairs({"PlayerList", "PlayerListGui", "RobloxGui", "InspectMenu", "AvatarContextMenu", "TopBarApp"}) do
                local f = cg:FindFirstChild(name, true)
                if f then scan(f) end
            end
        end)
    end

    ----------------------------------------------------------------
    -- Name / DisplayName text
    ----------------------------------------------------------------
    local function applyNames()
        local wantN, wantD = spoofName(), spoofDisplay()
        if not wantN and not wantD then return end
        local realN, realD = LocalPlayer.Name, LocalPlayer.DisplayName
        local function patch(lbl)
            if not (lbl:IsA("TextLabel") or lbl:IsA("TextButton") or lbl:IsA("TextBox")) then return end
            local t = lbl.Text
            if type(t) ~= "string" or t == "" then return end
            local nt = t
            if wantN and realN ~= "" then
                if nt == realN then nt = wantN else nt = nt:gsub(realN, wantN) end
            end
            if wantD and realD ~= "" and realD ~= realN then
                if nt == realD then nt = wantD else nt = nt:gsub(realD, wantD) end
            end
            -- if already showing spoof target mid-edit, keep
            if nt ~= t then pcall(function() lbl.Text = nt end) end
        end
        local function scan(root)
            if not root then return end
            for _, d in ipairs(root:GetDescendants()) do pcall(patch, d) end
        end
        scan(LocalPlayer:FindFirstChild("PlayerGui"))
        if LocalPlayer.Character then scan(LocalPlayer.Character) end
        pcall(function()
            local cg = game:GetService("CoreGui")
            for _, name in ipairs({"PlayerList", "PlayerListGui", "RobloxGui", "InspectMenu"}) do
                local f = cg:FindFirstChild(name, true)
                if f then scan(f) end
            end
        end)
    end

    ----------------------------------------------------------------
    -- Stats + FPS (Rivals fields)
    ----------------------------------------------------------------
    local function applyStatsAndFps()
        local keys = {
            "Winstreak","Level","CasualWins","RankedWins","CasualWinPercent","RankedWinPercent",
            "RankedElo","LeaderboardRank","Keys","EventCurrency","Fps","Ping"
        }
        local over = {}
        for _, k in ipairs(keys) do
            local on, v = field("LocalPlayer", k)
            if on and v ~= nil then over[k] = v end
        end
        if next(over) == nil then return end

        pcall(function()
            local ps = LocalPlayer:FindFirstChild("PlayerScripts")
            local c = ps and ps:FindFirstChild("Controllers")
            local pdc = c and c:FindFirstChild("PlayerDataController")
            if not pdc then return end
            local mod = require(pdc)
            local cur = mod and mod.CurrentData
            local data = cur and rawget(cur, "Data")
            if type(data) ~= "table" then return end
            for k, v in pairs(over) do
                pcall(function() data[k] = v end)
                pcall(function() data[k:lower()] = v end)
            end
        end)

        if over.Fps then
            local n = math.clamp(math.floor(tonumber(over.Fps) or 240), 1, 1000)
            pcall(function()
                LocalPlayer:SetAttribute("FPS", n)
                LocalPlayer:SetAttribute("Fps", n)
            end)
            pcall(function()
                local pg = LocalPlayer:FindFirstChild("PlayerGui")
                if not pg then return end
                for _, d in ipairs(pg:GetDescendants()) do
                    if d:IsA("TextLabel") or d:IsA("TextButton") then
                        local t = d.Text
                        if type(t) == "string" then
                            local low = t:lower():gsub("%s+", " ")
                            if low:match("^%d+ fps$") or low:match("^fps:? %d+$") then
                                pcall(function() d.Text = tostring(n) .. " FPS" end)
                            end
                        end
                    end
                end
            end)
        end
    end

    -- remove old fake overlay
    pcall(function()
        local pg = LocalPlayer:FindFirstChild("PlayerGui")
        local o = pg and pg:FindFirstChild("KyvweerFakeFPS")
        if o then o:Destroy() end
    end)

    task.spawn(function()
        for _ = 1, 50 do
            if store() then break end
            task.wait(0.1)
        end
        installHooks()
        local n = 0
        while true do
            n = n + 1
            pcall(applyBodyAvatar, false)
            pcall(applyNames)
            pcall(applyStatsAndFps)
            if n % 2 == 0 then pcall(applyAllFaces) end
            task.wait(0.35)
        end
    end)

    pcall(function()
        LocalPlayer.CharacterAdded:Connect(function()
            lastApplied = 0
            task.delay(0.25, function() applyBodyAvatar(true) end)
            task.delay(0.8, function() applyBodyAvatar(true) end)
            task.delay(1.6, function() applyBodyAvatar(true) end)
            task.delay(0.5, applyNames)
            task.delay(1.0, applyAllFaces)
        end)
    end)

    -- live UI additions (profile open)
    pcall(function()
        local pg = LocalPlayer:WaitForChild("PlayerGui", 30)
        if not pg then return end
        pg.DescendantAdded:Connect(function(d)
            task.defer(function()
                local uid = spoofUid()
                if not uid then return end
                if d:IsA("ImageLabel") or d:IsA("ImageButton") then
                    pcall(rewriteImage, d, tostring(LocalPlayer.UserId), uid)
                elseif d:IsA("TextLabel") or d:IsA("TextButton") then
                    pcall(applyNames)
                end
            end)
        end)
    end)

    print("[Kyvweer] Identity spoof runtime loaded (avatar+name+stats)")
end

